const top_kennen = {
  champion: '케넨',
  lane: 'top',
  patch: '26.22',
  matchups: {
    '가렌': { lv1: '1~2레벨에는 (Q)\'천둥의 표창\'으로 가렌의 체력을 깎으며 거리를 유지하세요. 가렌이 (Q)\'결정타\'를 사용해 빠르게 접근하면 뒤로 물러나 침묵을 피하는 것이 좋아요. 가렌이 (P)\'인내심\'으로 체력을 회복하지 못하도록 꾸준히 견제하세요.', lv3: '가렌이 (W)\'용기\'를 사용하면 보호막과 강인함을 얻으니 (W)\'전류 방출\'을 신중하게 사용하세요. (Q)\'결정타\'에 맞아 침묵이 걸리면 스킬을 쓸 수 없으니 주의해야 해요. (E)\'번개 질주\'를 활용해 가렌의 (E)\'심판\' 범위 밖으로 빠르게 움직이세요.', lv6: '(R)\'날카로운 소용돌이\'를 켜면 방어력과 마법 저항력을 얻으니 가렌이 붙는 구간에서 버티며 (P)\'폭풍의 표식\'을 쌓아 기절을 노려보세요. 가렌의 (R)\'데마시아의 정의\'는 잃은 체력에 비례한 고정 피해를 주므로 체력이 낮을 때는 조심해야 해요. 가렌이 붙으면 (E)\'번개 질주\'로 거리를 벌리며 대응하세요.', item: '첫 코어 아이템은 공격 속도와 주문력을 제공하는 내셔의 이빨을 선택해요. 신발은 가렌의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 가렌의 (P)\'인내심\' 회복을 억제하면 딜교환에서 더 앞서갈 수 있어요.' },
    '갱플랭크': { lv1: '갱플랭크는 (Q)\'혀어어어업상\'으로 멀리서 견제하며 골드를 챙기니 거리 조절에 신경 써야 해요. (Q)\'천둥의 표창\'을 맞춰 표식을 남기고 (W)\'전류 방출\'로 압박하며 갱플랭크가 다가오지 못하게 하세요. 1~2레벨에는 무리한 진입보다는 (Q)\'천둥의 표창\'을 활용한 견제와 파밍에 집중해요.', lv3: '(E)\'번개 질주\'로 진입하여 (W)\'전류 방출\'과 (Q)\'천둥의 표창\'을 섞어 딜교환을 하되 갱플랭크의 (W)\'괴혈병 치료\'가 빠졌는지 확인해야 해요. (E)\'화약통\'이 깔린 위치에서는 폭발 피해와 둔화를 입을 수 있으니 통 근처에서는 싸움을 피하세요. (E)\'번개 질주\'로 빠르게 접근한 뒤 (P)\'폭풍의 표식\'을 활용해 짧게 치고 빠지는 것이 좋아요.', lv6: '(R)\'날카로운 소용돌이\'를 사용하면 방어력과 마법 저항력을 얻으니 이를 이용해 적극적으로 교전하세요. 갱플랭크의 (R)\'포탄 세례\'가 깔리면 이동 속도가 느려지므로 장판 밖으로 빠르게 벗어나야 해요. (W)\'괴혈병 치료\'로 회복할 틈을 주지 않도록 (R)\'날카로운 소용돌이\' 범위 안에서 화력을 집중하세요.', item: '판금 장화와 루덴의 메아리를 가세요. 판금 장화는 갱플랭크의 기본 공격 피해를 줄여주고 루덴의 메아리는 스킬의 마법 피해를 높여줘요.', spell: '점멸과 점화를 추천해요. 점화로 갱플랭크의 (W)\'괴혈병 치료\' 회복 효과를 감소시키면 킬을 따내기 쉬워져요.' },
    '그라가스': { lv1: '그라가스는 (Q)\'술통 굴리기\'로 둔화를 걸고 (P)\'서비스 시간\'으로 체력을 회복하며 견제할 수 있어요. (Q)\'천둥의 표창\'으로 거리를 유지하며 미니언과 함께 견제하고, 술통이 터지는 위치를 잘 피하며 막타를 챙기세요. 1~2레벨에는 무리하게 붙지 말고 사거리를 활용해 일방적인 딜교환을 하세요.', lv3: '그라가스가 (E)\'몸통 박치기\'로 돌진해 기절을 노릴 수 있으니 주의하며 거리 조절을 하세요. (E)\'몸통 박치기\'를 피한 뒤에 (E)\'번개 질주\'로 빠르게 진입해 (Q)\'천둥의 표창\'과 (W)\'전류 방출\'로 폭발적인 피해를 입히세요. 그라가스가 (W)\'취중 분노\'를 사용하여 받는 피해를 줄이기 전에 스킬을 맞히는 것이 중요해요.', lv6: '(R)\'날카로운 소용돌이\'를 켜면 방어력과 마법 저항력을 얻고 주변 적에게 반복해서 피해를 줄 수 있어요. 그라가스의 (R)\'술통 폭발\'은 적을 폭발 지점에서 밀어내니 폭발 범위 중앙에 서지 말고 위치를 조절하세요. (E)\'번개 질주\'로 스킬 범위를 벗어나며 (R)\'날카로운 소용돌이\' 안에서 지속적으로 피해를 주세요.', item: '첫 코어 아이템으로 리치베인을 선택해 스킬을 쓴 뒤 다음 기본 공격에 추가 마법 피해를 넣으세요. 신발은 그라가스의 마법 피해와 군중 제어 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (P)\'서비스 시간\'으로 체력을 회복하는 그라가스에게 점화의 회복 감소가 도움이 되고, 마무리 피해로 킬각도 잡기 쉬워요.' },
    '그웬': { lv1: '1~2레벨에는 (Q)\'천둥의 표창\'으로 최대한 거리를 유지하며 견제하세요. 그웬이 (Q)\'싹둑싹둑!\'의 정면 원뿔 범위에 들어오지 않도록 주의하며 짧게 딜교환을 하세요. 평타 교환이 길어지면 (P)\'가위 난도질\'의 회복 때문에 그웬이 앞서가니 주의해야 해요.', lv3: '(E)\'돌격가위\'로 들어오는 타이밍에 (E)\'번개 질주\'로 거리를 벌리며 (Q)\'천둥의 표창\'을 맞히세요. 그웬이 (W)\'신성한 안개\'를 켜더라도 투사체인 (Q)\'천둥의 표창\'은 그대로 들어가니 계속해서 견제해요. (W)\'전류 방출\'은 표식이 쌓인 상태에서 사용해 기절을 노리며 짧은 딜교환을 반복하세요.', lv6: '(R)\'날카로운 소용돌이\'를 켜고 진입해 빠르게 기절을 시키면 킬각을 잡기 편해요. 하지만 (R)\'바느질\'에 맞으면 둔화되어 거리를 잡기 어려우니 바늘을 피하며 진입하세요. (R)\'날카로운 소용돌이\'의 방어력과 마법 저항력 증가 효과를 활용해 정글러의 갱킹 상황에서도 버티며 피해를 주세요.', item: '모렐로노미콘을 첫 코어로 가서 마법 피해를 줄 때 상처를 남겨 (P)\'가위 난도질\'의 회복을 줄이세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. (P)\'가위 난도질\'로 체력을 회복하는 그웬을 확실히 마무리하려면 점화의 치유 감소 효과가 필요해요.' },
    '나르': { lv1: '나르의 (Q)\'부메랑 던지기\'는 맞힌 뒤 돌아오니 궤적에서 옆으로 비켜 서세요. (Q)\'천둥의 표창\'으로 먼저 표식을 남기며 거리를 유지하고 미니언을 챙기세요. 부메랑이 빠진 틈에 (Q)\'천둥의 표창\'을 다시 맞혀 (P)\'폭풍의 표식\'을 쌓으세요.', lv3: '(E)\'번개 질주\'로 나르의 (Q)\'부메랑 던지기\'를 피하며 접근한 뒤 (Q)\'천둥의 표창\'과 (W)\'전류 방출\'로 빠르게 교환하세요. 나르가 (W)\'슝슝\'의 추가 피해를 입히려고 공격을 이어갈 때 거리를 벌려야 해요. (E)\'번개 질주\'가 끝난 뒤 상승하는 공격 속도를 활용해 (P)\'폭풍의 표식\'을 빠르게 터뜨리세요.', lv6: '메가 나르가 (R)\'나르!\'를 사용하여 적을 던질 때 (E)\'번개 질주\'를 사용해 위치를 빠르게 옮기며 피하세요. (R)\'날카로운 소용돌이\'를 사용하면 방어력과 마법 저항력을 얻어 메가 나르의 공격을 버티기 수월해요. 나르의 분노가 소진되어 작은 나르로 변했을 때 (R)\'날카로운 소용돌이\'를 켜고 딜을 집중하세요.', item: '리치베인으로 스킬 사용 후 평타로 강력한 피해를 입히세요. 신발은 나르의 물리 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 나르의 체력을 깎아 마무리하기 좋아요.' },
    '나서스': { lv1: '나서스가 (Q)\'흡수의 일격\'으로 미니언을 챙기려 할 때 (Q)\'천둥의 표창\'을 던져 체력을 깎으세요. 초반에는 나서스의 힘이 약하니 최대한 거리를 유지하며 미니언 막타 싸움을 방해해야 해요. (E)\'번개 질주\'를 활용해 무리하게 들어오는 나서스의 접근을 피하며 압박하세요.', lv3: '나서스의 (W)\'쇠약\'에 걸리면 이동 속도가 느려져 도망치기 어려우니 조심해야 해요. (Q)\'천둥의 표창\'으로 표식을 남긴 뒤 (W)\'전류 방출\'을 사용하여 폭발적인 피해를 입히는 딜교환을 하세요. 나서스가 (E)\'영혼의 불길\'을 사용하여 방어력을 낮추기 전에 먼저 스킬을 맞히고 빠지는 것이 중요해요.', lv6: '나서스가 (R)\'사막의 분노\'를 사용하면 체력이 늘어나고 공격 범위도 넓어지니 무리한 진입은 피하세요. (R)\'날카로운 소용돌이\'를 켜고 적진에서 싸우며 (P)\'폭풍의 표식\' 스택을 빠르게 쌓아 기절을 유도해야 해요. 라인을 빠르게 밀어 넣어서 나서스가 (Q)\'흡수의 일격\'으로 중첩을 쌓는 것을 방해하세요.', item: '리안드리의 고통을 첫 코어로 선택하여 체력이 높은 나서스에게 지속적인 피해를 입히세요. 신발은 마법 관통력을 얻을 수 있는 마법사의 신발을 추천해요.', spell: '점멸과 순간이동을 추천해요. 라인을 밀어 넣은 뒤 순간이동으로 다른 라인에 개입하거나 빠르게 복귀하며 성장을 도모하세요.' },
    '녹턴': { lv1: '(Q)\'천둥의 표창\'으로 계속 견제하며 거리를 유지하세요. (Q)\'황혼의 인도자\'에 맞으면 상대의 이동 속도가 증가해 접근하기 쉬워지니 주의하세요. 첫 웨이브에서는 미니언 뒤에서 짧은 딜교환만 하며 체력을 깎으세요.', lv3: '(E)\'말할 수 없는 공포\'에 걸리면 (E)\'번개 질주\'를 사용해 빠르게 범위를 벗어나 공포를 피하세요. (W)\'어둠의 장막\' 보호막이 켜졌을 때는 주요 스킬을 아껴두었다가 보호막이 사라진 뒤에 (W)\'전류 방출\'로 기절을 노리세요. (Q)\'천둥의 표창\'을 먼저 맞힌 뒤 접근하여 빠르게 표식을 쌓으세요.', lv6: '(R)\'피해망상\'으로 돌진해올 때 (R)\'날카로운 소용돌이\'를 켜서 맞대응하며 기절을 유도하세요. 시야가 차단된 상태에서는 정글러의 개입이 보이지 않으니 타워 근처에서 라인을 유지하세요. 상대의 돌진 직후에 (E)\'번개 질주\'로 위치를 잡으며 빠르게 스킬을 쏟아부으세요.', item: '판금 장화와 리안드리의 고통을 추천해요. 판금 장화는 (P)\'그림자 칼날\' 같은 기본 공격 피해를 줄여주고 리안드리의 고통은 체력을 제공하며 적을 불태워 피해를 입히기 좋아요.', spell: '점멸과 점화예요. 점멸은 생존과 킬각 잡기에 필수적이며 점화는 (P)\'그림자 칼날\'의 체력 회복 효과를 감소시키기 위해 사용하세요.' },
    '다리우스': { lv1: '(Q)\'천둥의 표창\'을 사용해 원거리에서 계속 견제하며 다리우스의 체력을 깎으세요. (Q)\'학살\'의 도끼날에 맞으면 상대의 회복량을 높여주니 사거리 밖에서 움직이며 (P)\'과다출혈\' 중첩이 쌓이지 않게 조심하세요. 최대한 거리를 유지하며 짧게 평타를 섞어 공격하세요.', lv3: '(E)\'포획\'에 끌려가면 (W)\'마비의 일격\' 둔화와 함께 큰 피해를 입으니 항상 사거리 밖에서 대기하세요. 상대의 (E)\'포획\'이 빠진 것을 확인한 뒤 (E)\'번개 질주\'로 빠르게 진입해 (Q)\'천둥의 표창\'과 평타로 기절을 노리세요. (W)\'전류 방출\'은 상대의 (P)\'과다출혈\' 중첩이 쌓이기 전 짧은 딜교환 마무리용으로 쓰세요.', lv6: '(R)\'날카로운 소용돌이\'를 켜고 진입해 (R)\'녹서스의 단두대\'를 쓰기 전에 피해를 입히세요. 하지만 (P)\'과다출혈\' 중첩이 높을 때 무리하게 붙으면 (R)\'녹서스의 단두대\'의 큰 고정 피해를 받을 수 있으니 주의하세요. 라인을 밀어두고 정글러를 부르거나 (E)\'번개 질주\'로 빠져나오며 개입을 피하세요.', item: '판금 장화는 다리우스의 기본 공격 피해를 줄여줘서 생존에 큰 도움이 돼요. 내셔의 이빨을 첫 코어로 선택해 공격 속도와 주문력을 챙겨 빠르게 기절을 시키세요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 (Q)\'학살\'을 통한 다리우스의 체력 회복을 억제하며 킬각을 잡으세요.' },
    '라이즈': { lv1: '라이즈는 (Q)\'과부하\'를 사용하여 멀리서 견제하니 미니언 뒤에 숨어 피해를 최대한 줄이세요. (Q)\'천둥의 표창\'을 사용하여 라이즈에게 표식을 남기며 파밍을 하되, 라이즈의 사거리 안에서 무리하게 평타를 치지는 마세요.', lv3: '라이즈가 (E)\'주문 전이\'를 맞힌 뒤 (W)\'룬 감옥\'을 사용하면 속박되니 (E)\'번개 질주\'를 활용해 거리를 조절하세요. (E)\'번개 질주\'로 진입하면서 (Q)\'천둥의 표창\'을 맞히고 (W)\'전류 방출\'을 사용하면 라이즈의 대응을 어렵게 만들 수 있어요.', lv6: '라이즈가 (R)\'공간 왜곡\'을 사용하여 위치를 이동하면 정글러의 개입을 조심하며 라인을 관리하세요. (R)\'날카로운 소용돌이\'를 사용하면 방어력과 마법 저항력을 얻으므로, 이를 활용해 라이즈의 스킬을 버티며 (W)\'전류 방출\'로 승부를 보세요.', item: '내셔의 이빨을 첫 코어로 선택해 공격 속도와 주문력을 동시에 챙기세요. 신발은 라이즈의 CC 지속시간을 줄여주는 헤르메스의 발걸음을 신으세요.', spell: '점멸과 점화를 추천해요. 라이즈의 CC를 피해 접근하고 (W)\'전류 방출\'로 마무리할 때 점화의 고정 피해가 큰 도움이 돼요.' },
    '럼블': { lv1: '럼블은 (Q)\'화염방사기\'를 사용해 근접 거리에서 강력한 피해를 입힐 수 있어요. (Q)\'천둥의 표창\'으로 멀리서 견제하며 (Q)\'화염방사기\' 사거리 안에 들어가지 않도록 거리를 조절하세요. 럼블이 (E)\'전기 작살\'로 둔화를 걸기 전에 (E)\'번개 질주\'를 활용해 거리를 벌리는 것이 좋아요.', lv3: '스킬이 모인 뒤에는 (E)\'번개 질주\'로 진입하여 (Q)\'천둥의 표창\'과 (W)\'전류 방출\'을 연계해 (P)\'폭풍의 표식\'을 터뜨리세요. 럼블이 (W)\'고철 방패\'를 사용하여 피해를 흡수할 수 있으니 방패가 빠진 것을 확인하고 싸우는 것이 효율적이에요. 럼블의 (E)\'전기 작살\'에 맞아 마법 저항력이 감소하지 않도록 주의하며 싸워야 해요.', lv6: '럼블이 (R)\'이퀄라이저 미사일\'을 깔면 그 궤적을 피해 (E)\'번개 질주\'로 빠르게 이탈하는 것이 중요해요. (R)\'날카로운 소용돌이\'를 사용해 (P)\'폭풍의 표식\'을 빠르게 쌓아 기절을 노리면 킬각을 잡을 수 있어요. 럼블이 궁극기를 사용한 뒤에는 화염의 벽 장판 위에서 머물지 말고 정글러의 위치를 확인하며 움직이세요.', item: '첫 코어로 내셔의 이빨을 선택해 공격 속도와 주문력을 함께 챙기세요. 신발은 럼블의 마법 피해와 (E)\'전기 작살\'의 군중 제어 효과를 견디기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 럼블이 (W)\'고철 방패\'로 버티는 상황에서 점화의 고정 피해로 확실하게 마무리할 수 있어요.' },
    '레넥톤': { lv1: '레넥톤은 (Q)\'양떼 도륙\'으로 체력을 회복하며 강하게 압박하니 (Q)\'천둥의 표창\'을 이용해 최대한 거리를 벌리며 견제하세요. 1~2레벨에는 상대가 분노를 쌓아 진입하기 전에 계속해서 표식을 남겨 압박하는 것이 중요해요. 레넥톤의 공격 사거리 밖에서 일방적으로 피해를 입히며 경험치를 챙기세요.', lv3: '레넥톤이 (E)\'자르고 토막내기\'로 진입할 때 (E)\'번개 질주\'를 사용해 빠르게 뒤로 빠지거나 위치를 옮기세요. 분노가 찬 상태의 (W)\'무자비한 포식자\'는 기절 시간이 길어 매우 위험하니, 상대의 분노 게이지를 확인하고 대응하세요. (Q)\'천둥의 표창\'으로 표식을 남긴 뒤 (W)\'전류 방출\'로 마무리하며 짧은 딜교환을 유도하세요.', lv6: '레넥톤이 (R)\'강신\'을 켜면 체력과 분노가 늘어나니 정면 승부보다 거리를 벌리며 (Q)\'천둥의 표창\'으로 시간을 끄세요. (R)\'날카로운 소용돌이\'는 상황에 따라 (R)\'강신\'이 끝난 뒤 진입할 때 켜거나, 레넥톤이 (E)\'자르고 토막내기\'로 붙었을 때 버티려고 켜는 것 중 하나로 쓰세요. 정글러와 협공하며 기절을 맞히면 킬각을 잡기 쉬워요.', item: '내셔의 이빨을 첫 코어로 선택해 공격 속도를 높여 표식을 빠르게 쌓으세요. 신발은 레넥톤의 기본 공격 피해를 줄여주는 판금 장화가 효율적이에요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 (Q)\'양떼 도륙\'의 회복량을 줄여야 딜교환에서 앞설 수 있어요.' },
    '렝가': { lv1: '(Q)\'천둥의 표창\'으로 계속 견제하며 수풀 근처에 가지 않도록 주의하세요. 렝가가 수풀에서 도약해 들어오면 빠르게 거리를 벌리며 평타를 섞어주세요. 첫 웨이브부터 거리 조절을 철저히 해서 체력 관리를 해야 해요.', lv3: '렝가의 (E)\'올가미 투척\'은 맞으면 둔화되고 야성이 가득 차면 속박되니 맞지 않도록 위치를 잡으세요. (Q)\'천둥의 표창\'과 기본 공격을 섞어 (P)\'폭풍의 표식\'을 쌓아 기절을 노리세요. 야성이 가득 찬 (W)\'전투의 포효\'는 군중 제어를 풀어 주니 그 전에 딜교환을 마무리하세요.', lv6: '(R)\'사냥의 전율\'로 렝가가 도약해 들어오는 순간 (R)\'날카로운 소용돌이\'를 켜서 맞대응하세요. 궁극기의 방어력과 마법 저항력 증가 효과로 렝가의 폭발적인 피해를 버텨내야 해요. 라인을 밀어두고 정글러의 개입을 대비해 깊게 들어가지 마세요.', item: '판금 장화와 존야의 모래시계를 추천해요. 판금 장화는 렝가의 기본 공격 피해를 줄여주고, 존야의 모래시계는 방어력과 함께 경직 상태로 위험한 순간을 넘기게 해요.', spell: '점멸과 점화를 추천해요. 점멸은 생존과 킬각 잡기에 필수적이며, 점화는 (W)\'전투의 포효\'로 회복하는 렝가의 체력 재생을 억제해요.' },
    '리븐': { lv1: '(Q)\'천둥의 표창\'을 사용해 거리 밖에서 계속 견제하세요. 리븐이 (Q)\'부러진 날개\'로 빠르게 진입하며 (P)\'룬 검\' 피해를 입히려 할 때 뒤로 물러나며 거리를 유지하세요.', lv3: '리븐의 (W)\'기 폭발\' 기절에 맞으면 일방적으로 공격당하니, 이 스킬이 빠진 것을 확인하고 (E)\'번개 질주\'로 진입해 짧게 딜교환하세요. (E)\'용맹\' 보호막이 켜져 있을 때는 (Q)\'천둥의 표창\'을 아꼈다가 보호막이 사라지는 타이밍에 맞추세요. (W)\'전류 방출\'로 기습적인 표식을 남겨 (P)\'폭풍의 표식\' 기절을 노리세요.', lv6: '리븐이 (R)\'추방자의 검\'을 사용해 원거리 공격으로 마무리를 노릴 때 주의하세요. 리븐이 (Q)\'부러진 날개\'로 진입하는 순간 (R)\'날카로운 소용돌이\'를 켜서 방어력과 마법 저항력을 얻고 역공하세요. 정글러가 올 때 궁극기를 활용해 광역 기절을 맞히면 쉽게 제압할 수 있어요.', item: '내셔의 이빨을 첫 코어로 가서 공격 속도와 주문력으로 (P)\'폭풍의 표식\'을 빠르게 터뜨리세요. 신발은 리븐의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 리븐의 체력이 낮을 때 점화로 마무리하여 처치하세요.' },
    '리산드라': { lv1: '리산드라가 (Q)\'얼음 파편\'으로 멀리서 견제하며 둔화를 걸 수 있으니 (Q)\'천둥의 표창\'을 던져 미니언과 함께 견제하며 거리를 유지하세요. 1~2레벨에는 리산드라의 스킬이 강력하니 무리하게 들어가기보다 파밍에 집중하며 대응해요.', lv3: '리산드라의 (W)\'서릿발\'에 속박되면 (E)\'번개 질주\'를 써도 움직일 수 없으니 가까이 붙지 않도록 거리를 유지하세요. (E)\'얼음갈퀴 길\'이 날아가는 방향을 예측해 (Q)\'천둥의 표창\'으로 표식을 쌓는 것이 중요해요. 상대의 스킬이 빠진 뒤에 (W)\'전류 방출\'로 (P)\'폭풍의 표식\'을 터뜨리며 딜교환을 해요.', lv6: '리산드라가 자신에게 (R)\'얼음 무덤\'을 쓰면 잠시 공격할 수 없는 상태가 되니 그동안 스킬을 아끼고 효과가 끝나는 순간을 노리세요. (R)\'날카로운 소용돌이\'는 상황에 따라 (E)\'번개 질주\'로 먼저 진입하며 켜거나, 리산드라가 (R)\'얼음 무덤\'을 쓴 뒤에 켜는 것 중 하나로 쓰세요. 상대의 궁극기 사용 여부를 확인하며 정글러의 개입에 대비해 라인 관리를 해요.', item: '마법 저항력과 공격 속도를 제공하는 마법사의 최후를 첫 코어로 올려 대응하세요. 신발은 리산드라의 (W)\'서릿발\'과 (R)\'얼음 무덤\' 군중 제어 지속 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 정화를 추천해요. 리산드라의 (R)\'얼음 무덤\' 기절이나 (W)\'서릿발\' 속박을 정화로 빠르게 풀고 다시 싸울 수 있어요.' },
    '마스터이': { lv1: '1~2레벨에는 (Q)\'천둥의 표창\'을 사용하여 마스터 이가 미니언을 먹으러 올 때마다 견제하세요. 마스터 이의 (P)\'2연속 공격\'이 위협적이니 적절한 거리를 유지하며 (E)\'번개 질주\'로 거리 조절을 해야 해요. 초반에는 무리하게 싸우기보다 스킬을 맞히며 체력을 깎아두는 것이 중요해요.', lv3: '3레벨에는 (Q)\'천둥의 표창\'으로 표식을 남긴 뒤 (W)\'전류 방출\'을 사용해 (P)\'폭풍의 표식\' 피해를 입히세요. 마스터 이가 (Q)\'일격 필살\'을 사용해 대상으로 지정할 수 없게 되면 공격을 멈추고 기다려야 해요. 마스터 이가 (W)\'명상\'을 켜면 딜교환을 중단하고 다시 거리를 벌리며 다음 기회를 노리세요.', lv6: '(R)\'날카로운 소용돌이\'를 사용하면 방어력과 마법 저항력을 얻어 마스터 이의 공격을 견디기 편해져요. 마스터 이가 (R)\'최후의 전사\'를 사용하면 둔화 효과가 통하지 않으니 무모한 추격보다는 (P)\'폭풍의 표식\'을 통한 기절을 노리세요. 마스터 이가 킬을 먹고 스킬 재사용 대기시간이 줄어들지 않게 정글러와 함께 압박하세요.', item: '첫 코어로 내셔의 이빨을 선택해 공격 속도와 주문력을 챙기세요. 신발은 마스터 이의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 마스터 이가 (W)\'명상\'을 사용하더라도 점화로 체력을 빠르게 깎아 확실하게 처치하세요.' },
    '마오카이': { lv1: '(Q)\'천둥의 표창\'으로 멀리서 마오카이의 체력을 깎으며 시작하세요. 마오카이가 (Q)\'덤불 주먹\'으로 다가올 때 (E)\'번개 질주\'를 사용하여 거리를 조절하세요. 1~2레벨에는 무리하게 맞붙기보다 견제 위주로 플레이하세요.', lv3: '마오카이의 (W)\'뒤틀린 전진\'은 적중하면 속박하고 돌진 중에는 대상으로 지정할 수 없으니 도약 거리 안에서 오래 머물지 마세요. (W)\'뒤틀린 전진\'이 빠진 직후에 (Q)\'천둥의 표창\'과 (W)\'전류 방출\'을 사용하여 (P)\'폭풍의 표식\'을 쌓으세요. (E)\'묘목 던지기\'가 설치된 수풀 주변에서는 교전을 피하세요.', lv6: '(R)\'날카로운 소용돌이\'를 사용해 근처 적들에게 마법 피해를 입히며 교전을 시작하세요. 마오카이가 (R)\'대자연의 마수\'로 벽을 세우면 옆으로 비켜 서서 속박을 피하세요. 마오카이의 주요 스킬이 빠진 상태라면 (R)\'날카로운 소용돌이\'로 강하게 압박하세요.', item: '첫 코어로 내셔의 이빨을 가서 공격 속도와 주문력을 챙기세요. 신발은 마법 저항력을 높여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 마오카이의 라인 압박에 대응하며 성장에 집중하기 좋아요.' },
    '말자하': { lv1: '말자하의 (P)\'공허 태세\'는 일정 시간 피해와 군중 제어를 받지 않으면 받는 피해가 줄고 군중 제어에 면역이 되니 (Q)\'천둥의 표창\'으로 먼저 피해를 입혀 효과를 끊어 주세요. (Q)\'공허의 부름\'은 문에서 투사체가 나가니 문이 열리는 위치에서 빠르게 벗어나세요. 1~2레벨에는 무리하게 진입하기보다 평타와 스킬로 짧게 견제하세요.', lv3: '(E)\'재앙의 환상\'에 걸리면 공허충이 몰려오고 지속 피해를 입으니 (E)\'번개 질주\'로 빠르게 진입했다가 짧게 치고 빠지세요. (Q)\'공허의 부름\' 침묵에 걸리기 전에 (W)\'전류 방출\'을 사용해 표식을 터뜨리고 기절을 노려야 해요. (W)\'공허의 무리\' 공허충이 소환되면 평타보다 스킬 위주로 빠르게 딜교환을 하세요.', lv6: '(R)\'황천의 손아귀\'는 제압이라 정화로 풀 수 없으니 상대의 궁극기 사거리를 주의하며 (R)\'날카로운 소용돌이\'를 켜고 진입하세요. 말자하가 (P)\'공허 태세\'를 켠 상태에서는 기절이 안 들어가니 먼저 피해를 입혀 효과를 끊는 것이 중요해요. 정글러가 오면 제압에 걸려 무력해질 수 있으니 라인을 적절히 밀며 시야를 확보하세요.', item: '내셔의 이빨로 주문력과 공격 속도를 챙겨 딜교환 능력을 높이세요. 신발은 마법 저항력을 얻고 침묵 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 순간이동을 추천해요. (R)\'황천의 손아귀\' 제압은 정화로 풀 수 없으니 운영에 도움이 되는 순간이동을 사용하세요.' },
    '말파이트': { lv1: '(P)\'화강암 방패\'가 켜져 있을 때는 평타 교환을 피하고 (Q)\'천둥의 표창\'으로 거리 조절을 하며 견제하세요. (Q)\'지진의 파편\'은 대상을 직접 지정하는 스킬이라 미니언 뒤에 숨어도 맞으니 맞은 뒤에는 무리하게 붙지 마세요. 상대의 보호막이 사라진 시점에 짧게 딜교환을 하고 빠지는 것이 좋아요.', lv3: '(E)\'지면 강타\'에 맞으면 공격 속도가 낮아져 (P)\'폭풍의 표식\'을 터뜨리기 어려우니 주의하세요. (E)\'번개 질주\'로 빠르게 진입해 (Q)\'천둥의 표창\'과 (W)\'전류 방출\'을 섞어 기절을 노리세요. (W)\'천둥소리\'가 활성화된 상태의 평타 범위에 오래 머물지 말고 짧게 치고 빠지는 구도를 잡으세요.', lv6: '(R)\'멈출 수 없는 힘\'은 저지 불가 상태로 돌진해 공중에 띄우므로 맞으면 스킬을 쓸 수 없어요. 상대가 돌진한 직후 (R)\'날카로운 소용돌이\'를 켜서 피해를 주고 방어력과 마법 저항력을 얻어 버티세요. 정글러가 근처에 있을 때는 (R)\'멈출 수 없는 힘\' 사거리 밖에서 라인을 관리하며 개입을 피하세요.', item: '내셔의 이빨을 첫 코어로 가서 공격 속도와 주문력을 높여 (P)\'폭풍의 표식\'을 빠르게 터뜨리세요. 신발은 마법 저항력을 높이고 (Q)\'지진의 파편\' 둔화 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 순간이동을 추천해요. 거리 조절이 중요한 매치업이며 (R)\'날카로운 소용돌이\'와 점멸을 연계해 한타 기여도를 높여야 해요.' },
    '모데카이저': { lv1: '모데카이저의 (Q)\'말살\'은 단일 대상에게 적중할 때 피해가 크니 미니언 옆에 서서 피해를 나누어 받으세요. (Q)\'천둥의 표창\'으로 계속 견제하면서 (P)\'암흑 탄생\' 오라가 켜지기 전에 짧은 거리만 유지하며 빠지세요. 첫 웨이브부터 무리하게 붙지 말고 거리 조절에 집중하세요.', lv3: '(E)\'죽음의 손아귀\'에 끌려가면 (Q)\'말살\' 연계에 노출되어 큰 피해를 입으니 항상 사거리 끝에서 움직이세요. (E)\'번개 질주\'로 끌어당기는 범위를 벗어나거나, 상대가 스킬을 헛썼을 때 들어가 (W)\'전류 방출\'과 함께 기절을 노리세요. 모데카이저가 (W)\'불멸\' 보호막을 켜기 전에 빠르게 딜교환을 마치고 물러나세요.', lv6: '(R)\'죽음의 세계\'에 끌려가면 순간이동으로 탈출할 수 없으니 끌려가기 전까지 최대한 거리를 벌리세요. 정면 승부를 해야 한다면 (R)\'날카로운 소용돌이\'를 켜서 방어력과 마법 저항력을 얻고 적을 기절시켜 피해를 최소화하세요. 정글러가 올 때 (E)\'죽음의 손아귀\'가 빠진 것을 확인하고 진입해 빠르게 처치하세요.', item: '내셔의 이빨을 첫 코어로 선택해 공격 속도를 높여 (P)\'폭풍의 표식\'을 빠르게 터뜨리세요. 신발은 모데카이저의 마법 피해를 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. (W)\'불멸\'의 체력 회복 효과를 점화로 줄여야 킬각을 잡기 편해요.' },
    '문도박사': { lv1: '문도 박사가 (Q)\'오염된 뼈톱\'을 던져 현재 체력 비례 피해를 입히고 둔화를 걸어요. (Q)\'오염된 뼈톱\'은 처음 맞는 대상에게 맞으니 미니언 뒤에 숨어서 피해를 피하세요. (Q)\'천둥의 표창\'으로 꾸준히 견제하며 거리 조절을 하는 것이 중요해요.', lv3: '문도 박사가 (W)\'심장 전기 충격\'을 켜고 다가오면 (E)\'번개 질주\'를 사용해 거리를 벌리세요. (P)\'가고 싶은 데로 간다\'가 준비된 상태라면 처음 걸리는 이동 불가 효과에 저항하니 이 효과를 먼저 뺀 뒤 다음 기절을 노리세요. (W)\'전류 방출\'과 (Q)\'천둥의 표창\'으로 짧게 딜교환을 해요.', lv6: '문도 박사가 (R)\'최대 투여량\'을 사용하면 체력을 즉시 회복하고 이동 속도도 빨라지니 주의하세요. (R)\'날카로운 소용돌이\'를 활용해 문도 박사의 회복량을 압도할 수 있는 타이밍에 진입해야 해요. 문도 박사의 궁극기가 빠진 것을 확인하고 (E)\'번개 질주\'로 거리를 좁히며 공격하세요.', item: '문도 박사의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 신발로 선택하세요. 첫 코어 아이템으로는 체력이 높은 문도 박사에게 지속적인 피해를 줄 수 있는 리안드리의 고통을 가세요.', spell: '점멸과 점화를 추천해요. 문도 박사의 회복량을 줄여야 킬각을 잡을 수 있어요.' },
    '바루스': { lv1: '바루스가 (Q)\'꿰뚫는 화살\'을 조준할 때 거리 조절에 유의하며 미니언을 챙기세요. (Q)\'천둥의 표창\'을 맞춰서 표식을 남기며 압박하되, 바루스의 평타에 (W)\'역병 화살\' 중첩이 쌓이지 않도록 조심해야 해요. 초반에는 무리하게 진입하기보다 거리를 유지하며 기회를 보세요.', lv3: '바루스가 (E)\'퍼붓는 화살\'로 지면을 오염시켜 이동 속도를 늦추면 그 위를 피해서 움직이세요. (E)\'번개 질주\'로 빠르게 접근하며 (Q)\'천둥의 표창\'과 (W)\'전류 방출\'을 연계해 (P)\'폭풍의 표식\' 스택을 쌓는 것이 중요해요. 바루스가 (Q)\'꿰뚫는 화살\'을 사용한 직후에 빈틈을 노려 짧게 교환하세요.', lv6: '(R)\'날카로운 소용돌이\'를 사용하면 방어력과 마법 저항력을 얻으니 이를 활용해 적극적으로 진입하세요. 바루스가 (R)\'부패의 사슬\'을 맞히면 이동이 차단되니 스킬을 피하거나 정글러를 불러야 해요. (E)\'번개 질주\'로 파고들어 표식을 터뜨리며 킬을 노려보세요.', item: '내셔의 이빨을 첫 코어로 올려서 공격 속도와 주문력을 동시에 챙기세요. 신발은 바루스의 (R)\'부패의 사슬\' 같은 군중 제어 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도로 바루스의 견제 사거리 안으로 빠르게 파고드는 것이 좋아요.' },
    '베인': { lv1: '베인은 (Q)\'구르기\'로 거리를 벌리며 (W)\'은화살\'의 중첩 피해를 노리니 무리하게 다가가지 마세요. (Q)\'천둥의 표창\'을 활용해 베인의 체력을 깎으며 거리 조절에 신경 써야 해요. 1~2레벨에는 미니언 뒤에서 (Q)\'천둥의 표창\'을 맞히며 파밍하는 것에 집중하세요.', lv3: '베인의 (E)\'선고\'는 대상 지정 스킬이라 피할 수 없으니 벽을 등지지 말고 라인 중앙에서 싸우세요. (E)\'선고\'가 빠진 직후 (E)\'번개 질주\'로 파고들어 (Q)\'천둥의 표창\'과 평타로 표식을 쌓으세요. (W)\'전류 방출\'로 (P)\'폭풍의 표식\'을 터뜨리며 딜교환을 마무리하세요.', lv6: '베인이 (R)\'결전의 시간\'을 켜고 (Q)\'구르기\'로 투명해지면 추격이 어려우니 주의하세요. (R)\'날카로운 소용돌이\'를 사용하여 베인이 접근할 때 기절시키며 몰아쳐야 해요. 베인이 (E)\'선고\'로 밀쳐내기 전에 궁극기를 먼저 사용하는 것이 중요해요.', item: '초반 코어 아이템으로 리치베인을 올려 딜교환 능력을 높이세요. 신발은 베인의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 베인은 회복 수단이 없으니 점화는 마무리 피해용으로 쓰세요. 점멸은 (E)\'선고\'의 사거리를 벗어나거나 진입 각을 만들 때 써요.' },
    '볼리베어': { lv1: '볼리베어는 (Q)\'번개 강타\'로 빠르게 접근해 기절을 걸려 해요. (Q)\'천둥의 표창\'으로 거리 조절을 하며 계속 견제하고, (Q)\'번개 강타\'가 활성화되어 달려올 때는 뒤로 물러나세요. 평타를 섞어 (P)\'폭풍의 표식\'을 쌓으면서 짧게 교환하고 빠지세요.', lv3: '(E)\'천공 분열\'의 둔화와 보호막을 조심하고, (E)\'번개 질주\'로 상대의 스킬 범위를 빠르게 벗어나세요. (W)\'광란의 상처\' 표식이 남은 상태에서 계속 붙어 있으면 체력을 회복하니 주의하세요. (Q)\'천둥의 표창\'과 평타, (W)\'전류 방출\'을 순서대로 사용해 기절을 먼저 시키고 빠르게 빠지세요.', lv6: '(R)\'폭풍을 부르는 자\'로 포탑을 비활성화하며 들어올 수 있으니 포탑 아래라고 방심하지 마세요. 볼리베어가 도약해 들어오는 순간 (R)\'날카로운 소용돌이\'를 켜고 (E)\'번개 질주\'로 위치를 잡으며 기절을 노리세요. 라인을 밀어 넣고 정글러와 함께 갱킹을 유도하는 것이 편해요.', item: '내셔의 이빨과 판금 장화를 추천해요. 판금 장화는 기본 공격 피해를 줄여주고 내셔의 이빨은 공격 속도를 높여 (P)\'폭풍의 표식\'을 빠르게 쌓게 해요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'광란의 상처\'의 체력 회복을 억제해 킬각을 잡으세요.' },
    '블라디미르': { lv1: '블라디미르는 (Q)\'수혈\'로 체력을 회복하며 견제하니 무리하게 맞붙지 마세요. (Q)\'천둥의 표창\'을 활용해 거리를 유지하며 상대의 체력을 깎아 두는 것이 좋아요. 1~2레벨에는 상대의 (Q)\'수혈\' 사거리에 들어가지 않도록 주의하며 파밍에 집중하세요.', lv3: '블라디미르가 (W)\'피의 웅덩이\'를 사용하면 공격 대상이 되지 않으므로 스킬을 아껴 두었다가 효과가 끝난 뒤에 사용하세요. (E)\'선혈의 파도\'는 미니언 뒤에 숨어서 피해를 줄이는 것이 중요해요. (E)\'번개 질주\'로 빠르게 접근한 뒤 (Q)\'천둥의 표창\'과 (W)\'전류 방출\'을 활용해 (P)\'폭풍의 표식\'을 터뜨리세요.', lv6: '블라디미르의 (R)\'혈사병\'에 감염되면 받는 피해가 늘어나니 감염된 동안은 교전을 피하고 거리를 벌리세요. (R)\'날카로운 소용돌이\'를 사용해 방어력과 마법 저항력을 얻으며 진입하고 (P)\'폭풍의 표식\'을 쌓으세요. 상대가 (W)\'피의 웅덩이\'를 사용해 빠져나간다면 (E)\'번개 질주\'로 거리를 좁히며 다음 기회를 노리세요.', item: '헤르메스의 발걸음과 내셔의 이빨을 추천해요. 상대의 마법 피해를 견디고 공격 속도와 주문력을 챙기기 위해서예요.', spell: '점멸과 점화를 추천해요. 점화는 블라디미르의 (Q)\'수혈\' 체력 회복 효과를 줄여주는 데 도움을 줘요.' },
    '뽀삐': { lv1: '1~2레벨에는 (Q)\'천둥의 표창\'을 이용해 거리 조절을 하며 계속해서 견제하세요. 뽀삐가 (Q)\'망치 강타\'로 느려지는 지대를 만들면 빠르게 벗어나서 피해를 줄이세요. (P)\'강철의 외교관\'으로 보호막을 얻으려 방패를 주우러 올 때 짧은 딜교환을 유도하세요.', lv3: '뽀삐가 (W)\'굳건한 태세\'를 켜면 이동 속도가 오르니 이때는 무리하게 붙지 말고 (Q)\'천둥의 표창\'으로 견제만 하세요. 효과가 끝난 뒤 (E)\'번개 질주\'와 (Q)\'천둥의 표창\'을 섞어 (P)\'폭풍의 표식\' 기절을 노리세요. (W)\'전류 방출\'은 표식이 있는 적에게 사용해 빠르게 피해를 입히고 거리를 벌리세요.', lv6: '(R)\'날카로운 소용돌이\'를 켜고 진입하되 (R)\'수호자의 심판\'에 맞으면 멀리 날아가 딜교환이 끊기니 주의하세요. 뽀삐가 (E)\'용감한 돌진\'으로 밀어붙여 벽에 부딪히면 기절하니 가급적 라인 중앙에서 싸우세요. 상대 정글러가 개입할 때 (R)\'날카로운 소용돌이\'의 방어력과 마법 저항력을 활용해 버티며 빠져나가세요.', item: '구인수의 격노검을 첫 코어로 가서 빠른 공격 속도로 표식을 쌓으세요. 신발은 뽀삐의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 점멸은 (E)\'용감한 돌진\' 벽 기절을 피하거나 (R)\'날카로운 소용돌이\' 킬각을 잡을 때 필요해요.' },
    '사이온': { lv1: '사이온의 (E)\'학살자의 포효\'는 미니언을 밀쳐내며 뒤의 적까지 맞히므로 미니언 뒤로 피하려 하지 마세요. (Q)\'천둥의 표창\'으로 거리를 유지하며 지속적으로 견제하고, 상대가 (Q)\'대량 학살 강타\'를 충전할 때 옆으로 피해 주세요. 거리 조절만 잘하면 초반에 체력 이득을 많이 챙길 수 있어요.', lv3: '사이온이 (W)\'영혼의 용광로\'로 보호막을 켜면 폭발할 때까지 잠시 거리를 두세요. (E)\'번개 질주\'를 이용해 (Q)\'대량 학살 강타\'의 충전 경로를 빠르게 벗어나며 표식을 남기세요. (W)\'전류 방출\'과 평타를 섞어 기절을 빠르게 시키고 바로 빠지는 짧은 딜교환을 반복하세요.', lv6: '(R)\'멈출 수 없는 맹공\'은 저지 불가 상태로 돌진하므로 돌진 중에 기절을 시키려 하지 말고 옆으로 비켜나세요. 돌진이 끝난 시점에 (R)\'날카로운 소용돌이\'를 켜서 피해를 주고 기절을 시키면 킬각을 잡기 좋아요. 처치 후에도 (P)\'영광스러운 죽음\'으로 잠시 되살아나 공격하니 완전히 사라질 때까지 거리를 유지하세요.', item: '리안드리의 고통을 첫 코어로 가서 체력이 높은 사이온에게 지속 피해를 입히세요. 신발은 사이온의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 사이온이 라인을 강하게 밀 때 순간이동으로 빠르게 복귀해 손해를 줄이는 것이 중요해요.' },
    '사일러스': { lv1: '(Q)\'천둥의 표창\'으로 계속 견제하며 사일러스의 접근을 막으세요. 사일러스가 (Q)\'사슬 후려치기\'를 쓰면 사슬이 교차하는 지점을 피해 거리 조절을 하세요. (P)\'페트리사이트 폭발\'이 충전된 평타를 맞지 않도록 주의하며 일방적으로 때려주세요.', lv3: '(E)\'도주 / 억압\'의 두 번째 돌진 사슬에 맞으면 공중으로 띄워지니 옆으로 피하며 거리 조절을 하세요. 사일러스가 (W)\'국왕시해자\'로 들어오면 (E)\'번개 질주\'로 빠르게 빠지거나 (Q)\'천둥의 표창\'을 맞춰 표식을 남기세요. 표식이 쌓였을 때 (W)\'전류 방출\'을 써서 기절시키면 사일러스의 진입 흐름을 끊을 수 있어요.', lv6: '사일러스는 (R)\'강탈\'로 내 (R)\'날카로운 소용돌이\'를 훔쳐 쓸 수 있고 내가 궁극기를 썼는지와 상관없으니 훔친 효과에 대비하세요. (E)\'도주 / 억압\'이 빠진 시점에 (R)\'날카로운 소용돌이\'를 켜고 붙으면 피해를 주기 좋아요. 사일러스는 (W)\'국왕시해자\'로 체력을 회복하니 정글러와 함께 공격하거나 빠르게 피해를 입히세요.', item: '모렐로노미콘을 첫 코어로 선택해 (W)\'국왕시해자\'의 체력 회복량을 줄이세요. 신발은 마법 저항력을 높여주고 강인함으로 군중 제어 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. (W)\'국왕시해자\'의 회복 효과를 억제하고 킬 결정력을 높이기 위해 점화가 필요해요.' },
    '세주아니': { lv1: '1~2레벨에는 세주아니의 (Q)\'혹한의 맹습\' 돌진을 조심하며 거리를 유지해요. (Q)\'천둥의 표창\'을 활용해 멀리서 적의 체력을 깎으며 파밍에 집중하세요. 상대가 다가오려 하면 무리하지 말고 뒤로 물러나며 피해를 최소화해요.', lv3: '3레벨 이후에는 (Q)\'천둥의 표창\'을 먼저 맞춰 표식을 남기고 (W)\'전류 방출\'로 딜교환을 시도해요. 세주아니의 (E)\'만년 서리\' 기절이 사용되지 않도록 주의하면서 (E)\'번개 질주\'로 거리를 조절하세요. 상대의 (W)\'혹한의 서릿발\' 둔화를 맞았다면 즉시 거리를 벌려야 해요.', lv6: '6레벨이 되면 (R)\'날카로운 소용돌이\'를 사용해 광역 피해를 입히며 전투를 주도해요. 세주아니의 (R)\'빙하 감옥\' 기절을 맞으면 위험하니 (E)\'번개 질주\'로 위치를 빠르게 옮기세요. 정글러를 부를 때는 라인을 당겨서 상대의 진입을 억제하며 싸워요.', item: '헤르메스의 발걸음과 리안드리의 고통을 가요. 세주아니의 마법 피해에 대응하고 지속적인 피해를 입히기 위해서예요.', spell: '점멸과 정화를 추천해요. 정화로 (E)\'만년 서리\'나 (R)\'빙하 감옥\'의 기절은 풀 수 있지만 (Q)\'혹한의 맹습\'의 에어본은 풀 수 없어요.' },
    '세트': { lv1: '세트가 (Q)\'주먹다짐\'을 켜고 달려들 때 평타 거리를 주지 말고 뒤로 물러나세요. (Q)\'천둥의 표창\'을 적중시켜 표식을 남기며 견제하세요. 초반 평타 교환은 (P)\'투기장의 투지\'의 회복 때문에 세트가 강하니 맞붙지 마세요.', lv3: '(E)\'안면 강타\'는 세트 양옆에 적이 하나씩 있으면 기절시키니 세트를 사이에 두고 내 미니언과 반대편에 서지 마세요. 세트가 투지를 많이 쌓아 (W)\'강펀치\'의 중심선 고정 피해를 날리려 하면 (E)\'번개 질주\'로 빠르게 옆으로 피하세요. (W)\'전류 방출\'과 (Q)\'천둥의 표창\'으로 표식을 빠르게 쌓아 기절시키고 거리를 벌리는 딜교환을 하세요.', lv6: '세트의 (R)\'대미 장식\'은 제압이라 붙잡히면 (R)\'날카로운 소용돌이\'를 쓸 수 없으니 교전을 열 때 미리 켜서 방어력과 마법 저항력을 얻으세요. 특히 세트가 (E)\'안면 강타\'를 헛친 직후가 궁극기를 켜고 진입하기 좋은 타이밍이에요. 정글러가 가까이 있으면 (R)\'대미 장식\' 사거리 밖에서 움직이며 라인을 관리하세요.', item: '마법공학 로켓 벨트로 돌진기를 확보해 세트의 스킬을 피하고 거리 조절을 하세요. 신발은 (Q)\'주먹다짐\' 같은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (P)\'투기장의 투지\'로 체력을 회복하는 세트의 유지력을 점화의 치유 감소로 억제하세요.' },
    '쉔': { lv1: '쉔이 (Q)\'황혼 강습\'으로 기의 검을 가져올 때 거리를 조절하며 (Q)\'천둥의 표창\'을 맞춰 견제하세요. 쉔은 스킬을 사용하며 (P)\'기 보호막\'을 얻으니 보호막이 없을 때 평타와 스킬을 섞어 압박하세요. 초반에는 쉔의 기의 검이 챔피언에게 닿지 않도록 주의하며 파밍에 집중하세요.', lv3: '쉔이 (E)\'그림자 돌진\'을 사용하면 도발에 걸려 스킬을 쓸 수 없으니 주의해야 해요. 쉔의 (W)\'의지의 결계\'가 켜져 있는 동안은 평타가 막히므로 (E)\'번개 질주\'로 거리를 벌리거나 (Q)\'천둥의 표창\'으로 견제만 하세요. 쉔의 도발이 빠진 뒤에 (W)\'전류 방출\'을 활용해 (P)\'폭풍의 표식\'을 터뜨리며 딜교환을 하세요.', lv6: '쉔이 (R)\'단결된 의지\'를 사용해 다른 라인에 합류하면 라인을 빠르게 밀어 압박하세요. 쉔이 궁극기로 자리를 비운 사이 (R)\'날카로운 소용돌이\'를 활용해 킬각을 노리거나 포탑을 압박하면 좋아요. 쉔이 다시 돌아올 때는 (E)\'번개 질주\'를 사용하여 쉔의 (E)\'그림자 돌진\'을 피하며 거리를 유지하세요.', item: '리안드리의 고통을 첫 코어로 선택해 체력이 높은 쉔에게 지속적인 피해를 주세요. 신발은 (E)\'그림자 돌진\'의 도발 지속 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 쉔은 회복 수단이 없으니 점화는 (P)\'기 보호막\'이 빠진 뒤 마무리 피해용으로 쓰세요.' },
    '쉬바나': { lv1: '(Q)\'천둥의 표창\'으로 쉬바나의 체력을 깎으며 거리를 유지하세요. 쉬바나가 (Q)\'잉걸불 일격\'을 사용해 다가오지 못하도록 주의해야 해요. 초반에는 미니언을 챙기며 성장에 집중하는 것이 좋아요.', lv3: '(E)\'번개 질주\'를 사용하여 쉬바나의 (E)\'용암 분출\'을 피하며 거리를 조절하세요. (Q)\'천둥의 표창\'을 맞힌 뒤 (W)\'전류 방출\'을 사용해 (P)\'폭풍의 표식\'을 빠르게 쌓는 것이 중요해요. 쉬바나가 (W)\'지옥불 방패\'로 보호막을 얻으면 교환을 피하세요.', lv6: '쉬바나가 (R)\'용의 강림\'으로 저지 불가 상태가 되어 날아올 때는 (R)\'날카로운 소용돌이\'를 신중하게 사용하세요. 용 형상의 쉬바나는 (W)\'지옥불 방패\'로 체력을 회복할 수 있으니 주의해야 해요. 정글러와 함께 (R)\'날카로운 소용돌이\'로 킬을 노려보세요.', item: '헤르메스의 발걸음과 리안드리의 고통을 가세요. 마법 저항력과 강인함을 위해 헤르메스의 발걸음을 사고, 지속적인 피해를 위해 리안드리의 고통을 선택해요.', spell: '점멸과 점화를 사용해요. 쉬바나를 빠르게 제압하고 마무리 피해를 입히기 위해 선택해요.' },
    '스웨인': { lv1: '스웨인은 (Q)\'죽음의 손길\'로 견제하며 (P)\'굶주린 새떼\' 조각을 모아 체력을 늘려요. (Q)\'천둥의 표창\'으로 멀리서 먼저 표식을 남기고 평타를 섞어 체력을 깎으세요. 번개가 퍼지는 경로를 피해 옆으로 움직이며 거리 조절을 하는 게 중요해요.', lv3: '(E)\'속박명령\'은 돌아올 때 속박하므로 파동이 나가는 순간 (E)\'번개 질주\'로 빠르게 피하세요. 속박이 빠진 뒤 (Q)\'천둥의 표창\'과 (W)\'전류 방출\'을 섞어 (P)\'폭풍의 표식\' 기절을 노리며 딜교환을 하세요. (W)\'제국의 눈\'의 둔화에 걸리면 거리 조절이 어려우니 최대한 피하면서 싸워요.', lv6: '스웨인이 (R)\'악의 승천\'으로 변신해 체력을 흡수하면 (R)\'날카로운 소용돌이\'로 방어력과 마법 저항력을 얻으며 맞서세요. 하지만 무작정 붙어 있으면 흡수량만 늘어나니 기절을 시킨 뒤 빠르게 빠져나오세요. (W)\'제국의 눈\'으로 위치가 드러나니 정글러의 갱킹에 노출되지 않게 라인 관리를 하세요.', item: '내셔의 이빨을 첫 코어로 선택해 공격 속도와 주문력을 높여 빠르게 표식을 쌓으세요. 신발은 (E)\'속박명령\'의 속박 지속시간을 줄이는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. (R)\'악의 승천\'과 (P)\'굶주린 새떼\'의 강력한 체력 회복을 점화로 억제해야 해요.' },
    '스카너': { lv1: '(Q)\'천둥의 표창\'으로 계속 거리 조절을 하며 견제하세요. 스카너가 (Q)\'부서진 대지/지반 돌출\'의 바위를 던져 둔화를 걸려고 하면 무빙으로 피하며 체력을 깎아두세요.', lv3: '스카너가 (E)\'이쉬탈의 격돌\'로 돌진해 벽으로 밀어붙이려 할 때 (E)\'번개 질주\'로 빠르게 피하세요. (Q)\'천둥의 표창\'과 (W)\'전류 방출\'을 섞어 (P)\'폭풍의 표식\'을 빠르게 터뜨려 기절시키고 빠져나와야 해요.', lv6: '스카너의 (R)\'꿰뚫기\' 제압에 걸리면 (R)\'날카로운 소용돌이\'를 쓸 수 없으니 주의하세요. 제압 사거리 밖에서 (R)\'날카로운 소용돌이\'를 켜고 진입해 기절을 맞히면 정글러와 함께 적을 처치하기 편해요.', item: '판금 장화와 내셔의 이빨을 추천해요. 판금 장화는 기본 공격 피해를 줄여주고 내셔의 이빨은 공격 속도를 높여 기절을 빠르게 맞히게 도와줘요.', spell: '점멸과 순간이동을 추천해요. (R)\'꿰뚫기\'나 (E)\'이쉬탈의 격돌\'의 위협적인 진입을 점멸로 피하고 탑 라인 복귀를 위해 순간이동을 사용하세요.' },
    '신지드': { lv1: '신지드가 (Q)\'맹독의 자취\'를 켜고 다가오면 거리를 벌리며 (Q)\'천둥의 표창\'으로 계속 견제하세요. (P)\'독성 급류\' 때문에 붙으면 빠르게 도망가기 어려우니 적절한 간격을 유지하며 막타를 챙기세요. 무리하게 쫓아가다 독구름에 들어가지 않도록 주의하세요.', lv3: '(W)\'초강력 접착제\' 위에서는 (E)\'번개 질주\'를 사용할 수 없으니 접착제가 깔린 곳은 빠르게 피하세요. (E)\'던져넘기기\'로 던져져 접착제 위에 착지하면 속박되니 위치 선정에 유의하세요. 상대의 접착제가 빠진 타이밍에 (E)\'번개 질주\'로 진입해 (Q)\'천둥의 표창\'과 (W)\'전류 방출\'로 기절을 노리세요.', lv6: '(R)\'광기의 물약\'을 마신 신지드는 체력 재생력이 높아지니 지속 교전보다는 순간적인 폭딜을 노리세요. (R)\'날카로운 소용돌이\'를 켜면 방어력과 마법 저항력이 오르니 신지드가 (E)\'던져넘기기\'로 붙으려 할 때 사용해 빠르게 기절시키세요. 라인을 밀어넣고 정글러와 함께 신지드를 압박하는 구도를 만드세요.', item: '내셔의 이빨을 첫 코어로 가서 공격 속도와 주문력을 챙겨 기절을 더 빠르게 발동시키세요. 신발은 (Q)\'맹독의 자취\'의 마법 피해를 줄이고 (W)\'초강력 접착제\'의 둔화 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 정화를 추천해요. (W)\'초강력 접착제\'의 둔화와 이동 스킬 제한, 그리고 (E)\'던져넘기기\' 이후의 속박을 정화로 즉시 풀 수 있어요.' },
    '신짜오': { lv1: '(Q)\'천둥의 표창\'으로 멀리서 꾸준히 견제하며 상대의 체력을 깎아두세요. 신 짜오가 (Q)\'삼조격\'으로 공중으로 띄우지 못하도록 거리를 유지하는 것이 중요해요. 1~2레벨 구간에서는 무리하게 싸우지 말고 미니언을 챙기며 조심하세요.', lv3: '신 짜오가 (E)\'무쌍돌격\'으로 들어오면 (E)\'번개 질주\'를 사용하여 빠르게 거리를 조절하세요. (Q)\'천둥의 표창\'과 (W)\'전류 방출\'을 적절히 섞어 (P)\'폭풍의 표식\'을 쌓아 기절을 노리는 것이 좋아요. 상대의 (W)\'풍전참뢰\' 둔화가 빠진 뒤에 딜교환을 시도하세요.', lv6: '(R)\'날카로운 소용돌이\'를 사용해 광역 피해를 입히고 방어력을 높여 전투를 이끄세요. 다만 신 짜오가 (R)\'현월수호\'를 사용해 공격을 피하며 밀쳐내지 않도록 주의해야 해요. 6레벨 이후에는 상대의 돌진기가 빠진 것을 확인한 후 궁극기로 진입하여 기절을 시키세요.', item: '판금 장화와 내셔의 이빨을 추천해요. 판금 장화는 신 짜오의 물리 피해를 줄여주며, 내셔의 이빨은 공격 속도를 높여 (P)\'폭풍의 표식\'을 더 빠르게 터뜨리게 도와줘요.', spell: '점멸과 점화를 추천해요. 점멸은 (R)\'날카로운 소용돌이\'로 진입할 때 유용하며, 점화는 (P)\'결심\'을 통한 상대의 체력 회복을 억제하기 위해 필요해요.' },
    '아이번': { lv1: '(Q)\'천둥의 표창\'으로 견제하며 아이번의 (Q)\'덩굴뿌리\'에 맞지 않도록 거리를 조절하세요. 아이번이 (W)\'수풀 가꾸기\'를 사용해 시야를 가리려 하면 무리하게 들어가지 말고 거리를 유지해요. 초반에는 상대의 속박을 조심하며 미니언을 챙기는 것에 집중하세요.', lv3: '아이번의 (Q)\'덩굴뿌리\'가 빠진 것을 확인한 뒤 (W)\'전류 방출\'과 (Q)\'천둥의 표창\'을 활용해 딜교환을 시도하세요. 상대가 (E)\'보호의 씨앗\'을 사용하여 보호막을 얻으면 바로 진입하지 말고 기다려야 해요. (E)\'번개 질주\'를 사용하여 상대의 스킬을 피하며 (P)\'폭풍의 표식\'을 쌓으세요.', lv6: '아이번이 (R)\'데이지!\'를 소환하면 에어본을 주의하며 (R)\'날카로운 소용돌이\'를 사용하세요. 상대의 (E)\'보호의 씨앗\' 둔화를 (E)\'번개 질주\'로 극복하며 진입하는 것이 중요해요. 정글러의 지원을 받아 아이번이 (R)\'데이지!\'와 함께 교전할 때를 노려보세요.', item: '헤르메스의 발걸음과 내셔의 이빨을 추천해요. 헤르메스의 발걸음으로 (Q)\'덩굴뿌리\' 속박 지속시간을 줄이고, 내셔의 이빨로 공격 속도와 주문력을 높여요.', spell: '점멸과 점화를 추천해요. 순간적인 피해를 더 입혀서 아이번을 빠르게 처치하기 위해서예요.' },
    '아지르': { lv1: '1~2레벨에는 아지르의 (Q)\'사막의 맹습\' 둔화를 조심하며 (Q)\'천둥의 표창\'으로 먼저 견제해야 해요. 미니언을 챙기면서 아지르가 (W)\'일어나라!\'를 사용해 거리를 유지하는 것을 방해하세요. 아지르가 공격을 시작하면 (E)\'번개 질주\'를 사용하여 거리를 좁힐 준비를 해요.', lv3: '3레벨에는 (E)\'번개 질주\'를 사용하여 빠르게 접근한 뒤 (Q)\'천둥의 표창\'과 (W)\'전류 방출\'을 섞어 딜교환을 해요. 아지르의 (Q)\'사막의 맹습\'에 맞으면 둔화가 걸리니 (E)\'번개 질주\'의 이동 속도로 거리를 조절하세요. 아지르가 (E)\'신기루\' 보호막을 사용하면 무리하게 들어가지 말고 스킬이 빠진 뒤에 다시 시도해요.', lv6: '6레벨 이후에는 (R)\'날카로운 소용돌이\'를 사용하여 한타나 킬각을 노릴 수 있어요. 아지르가 (R)\'황제의 진영\'으로 밀어내기 전에 (E)\'번개 질주\'로 진입하는 것이 중요해요. 아지르의 (R)\'황제의 진영\'에 밀려나면 딜을 넣기 어려우니 정글러를 부를 때 신중하게 행동하세요.', item: '헤르메스의 발걸음과 내셔의 이빨을 가세요. 아지르의 마법 피해를 견디기 위해 마법 저항력이 있는 헤르메스의 발걸음을 사고 공격 속도를 높이기 위해 내셔의 이빨을 선택해요.', spell: '점멸과 유체화를 추천해요. 유체화로 아지르의 거리 조절을 뚫고 (E)\'번개 질주\'와 함께 빠르게 접근할 수 있어요.' },
    '아칼리': { lv1: '(Q)\'천둥의 표창\'을 이용해 거리 조절을 하며 계속 견제하세요. 아칼리가 (Q)\'오연투척검\'으로 둔화를 걸며 다가올 때 평타를 섞어 (P)\'폭풍의 표식\'을 쌓으세요. 아칼리의 (P)\'암살자의 표식\' 원 경계 근처에 서 있지 않도록 주의하며 거리 유지를 해요.', lv3: '아칼리가 (E)\'표창곡예\'로 진입하려고 하면 (E)\'번개 질주\'로 빠르게 위치를 옮겨 피하세요. (W)\'황혼의 장막\' 안에서는 대상 지정 스킬이 안 통하므로, 범위 공격인 (W)\'전류 방출\'을 사용해 피해를 입히세요. (P)\'폭풍의 표식\'을 빠르게 쌓아 기절시킨 뒤 빠르게 빠지는 딜교환을 해요.', lv6: '아칼리가 (R)\'무결처형\'으로 들어올 때 (R)\'날카로운 소용돌이\'를 켜서 방어력과 마법 저항력을 얻고 대응하세요. (R)\'날카로운 소용돌이\'는 범위 피해라 (W)\'황혼의 장막\' 안의 아칼리에게도 피해를 입힐 수 있어요. 아칼리의 체력이 낮아질 때까지 기다렸다가 기절 연계로 킬각을 잡으세요.', item: '존야의 모래시계는 방어력을 제공하고 아칼리의 폭발적인 피해를 한 턴 버티게 해줘요. 신발은 마법 저항력을 높여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 탈진을 추천해요. 탈진으로 아칼리의 폭발적인 피해량을 줄여 생존력을 높이세요.' },
    '아크샨': { lv1: '아크샨이 (Q)\'복수의 부메랑\'을 사용하여 견제하므로 거리를 유지하는 것이 중요해요. (Q)\'천둥의 표창\'을 활용해 멀리서 표식을 남기며 적의 체력을 깎으세요. 상대가 평타로 공격하기 쉬운 위치에 서지 않도록 주의하며 파밍을 진행해요.', lv3: '(E)\'번개 질주\'를 사용하여 빠르게 접근하거나 아크샨의 (E)\'영웅의 비상\' 돌진을 피하는 것이 핵심이에요. (W)\'전류 방출\'을 사용해 (P)\'폭풍의 표식\'이 남은 적에게 피해를 주며 딜교환을 시도하세요. 아크샨이 (P)\'비열한 싸움\'으로 보호막을 얻지 못하게 조절하며 싸워요.', lv6: '(R)\'날카로운 소용돌이\'를 사용하여 적진에서 버티며 마법 피해를 입히는 플레이를 하세요. 아크샨의 (R)\'인과응보\'는 체력이 낮은 적에게 강력하므로 체력 관리에 신경 써야 해요. 라인을 관리하며 정글러의 개입을 유도하거나 신중하게 움직이세요.', item: '판금 장화와 라일라이의 수정홀을 가세요. 판금 장화는 아크샨의 기본 공격 피해를 줄여주고, 라일라이의 수정홀은 적에게 둔화를 걸어 아크샨의 움직임을 제약하기 좋아요.', spell: '점멸과 점화를 추천해요. 아크샨은 회복 수단이 없으니 점화는 마무리 피해용으로 쓰세요.' },
    '아트록스': { lv1: '아트록스가 (Q)\'다르킨의 검\' 끝자락을 맞히지 못하도록 거리 조절을 하며 (Q)\'천둥의 표창\'으로 견제하세요. 1~2레벨에는 무리하게 맞대결하지 말고 (Q)\'천둥의 표창\'을 맞춰서 (P)\'폭풍의 표식\'을 쌓는 데 집중하세요. 아트록스의 (P)\'사신 태세\' 평타는 회복을 동반하니 주의해야 해요.', lv3: '아트록스의 (W)\'지옥사슬\' 범위 안에 갇히지 않게 주의하며 (E)\'번개 질주\'를 이용해 위치를 잡으세요. 아트록스가 (Q)\'다르킨의 검\'을 사용할 때 (Q)\'천둥의 표창\'과 (W)\'전류 방출\'로 (P)\'폭풍의 표식\'을 빠르게 쌓으세요. 아트록스의 (E)\'파멸의 돌진\'이 빠진 타이밍에 스킬을 맞춰서 딜교환을 시도하세요.', lv6: '아트록스가 (R)\'세계의 종결자\'를 켜면 공격력과 회복량이 늘어나니 정면 싸움은 피하는 것이 좋아요. (R)\'날카로운 소용돌이\'로 방어력과 마법 저항력을 얻은 뒤 (E)\'번개 질주\'로 진입해 (P)\'폭풍의 표식\'을 터뜨리세요. 아트록스가 궁극기로 미니언에게 공포를 주며 압박하면 라인을 당겨서 받아먹으세요.', item: '판금 장화와 내셔의 이빨을 가세요. 판금 장화는 아트록스의 물리 피해를 줄여주고 내셔의 이빨은 주문력과 공격 속도를 높여줘요.', spell: '점멸과 점화를 추천해요. 점화는 아트록스의 (P)\'사신 태세\'와 (E)\'파멸의 돌진\'에 의한 체력 회복을 감소시켜요.' },
    '암베사': { lv1: '1~2레벨에는 (Q)\'천둥의 표창\'으로 계속 견제하며 거리를 유지하세요. 암베사가 (P)\'용사냥개의 발걸음\'으로 빠르게 진입해 (Q)\'교활한 휩쓸기\'를 쓰려 할 때 옆으로 피해 주세요. 무리하게 붙지 말고 원거리에서 표식을 남기며 압박하는 게 좋아요.', lv3: '암베사가 (W)\'배척\' 보호막을 켜고 준비할 때 피해를 주면 내려치는 피해가 커지니 잠시 뒤로 물러나세요. (E)\'찢어 가르기\'의 둔화에 걸리기 전에 (E)\'번개 질주\'로 빠르게 위치를 옮겨 회피하세요. (Q)\'천둥의 표창\'과 (E)\'번개 질주\'로 표식을 쌓은 뒤 (W)\'전류 방출\'로 기절시켜 상대의 진입 흐름을 끊으세요.', lv6: '(R)\'공개 처형\'은 사거리가 길어 멀리서도 순간 이동해 제압하니 체력이 낮을 때 방심하지 마세요. 제압 상태에서는 (R)\'날카로운 소용돌이\'를 켤 수 없으니 교전이 시작되면 미리 켜서 방어력과 마법 저항력을 얻으세요. 정글러가 오면 기절 연계로 반격해 킬각을 잡으세요.', item: '판금 장화를 신어 암베사의 기본 공격 피해를 줄이세요. 존야의 모래시계를 첫 코어로 선택해 방어력으로 물리 피해를 버티고 위험한 순간 경직 상태로 시간을 버세요.', spell: '점멸과 점화를 추천해요. 암베사는 (R)\'공개 처형\'의 기본 지속 효과로 스킬 피해의 일부만큼 체력을 회복하니 점화로 회복을 억제하며 처치하세요.' },
    '애니비아': { lv1: '애니비아는 (Q)\'냉기 폭발\'의 사거리가 더 길어서 기절을 노리며 견제해요. 구체가 날아오는 경로를 보고 옆으로 피해 준 뒤 (Q)\'천둥의 표창\'으로 응수하세요. 초반에는 구체에 맞지 않도록 주의하며 거리 조절을 하세요.', lv3: '(W)\'결정화\'로 길이 막히면 (E)\'번개 질주\'로도 벽을 지나갈 수 없으니 벽이 녹을 때까지 기다리거나 돌아가세요. (Q)\'냉기 폭발\'이 빠진 틈을 타 (Q)\'천둥의 표창\'과 (W)\'전류 방출\'을 맞춰 (P)\'폭풍의 표식\' 기절을 노리세요. (E)\'동상\'은 냉각 상태일 때 피해가 크니 구체에 맞았다면 잠시 물러나세요.', lv6: '(R)\'얼음 폭풍\'의 둔화 속에서도 (E)\'번개 질주\'로 진입해 (R)\'날카로운 소용돌이\'를 켜고 빠르게 기절을 넣으세요. 애니비아가 (P)\'환생\'으로 알이 되면 즉시 알을 공격해 파괴하세요. (R)\'날카로운 소용돌이\'의 방어력과 마법 저항력 증가 효과를 활용해 버티며 싸우세요.', item: '균열 생성기를 가서 체력과 주문력을 챙기고 지속 전투 능력을 높이세요. 신발은 (Q)\'냉기 폭발\'의 기절과 (R)\'얼음 폭풍\'의 둔화 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 정화를 추천해요. (Q)\'냉기 폭발\'의 기절을 정화로 즉시 풀고 진입할 수 있어요.' },
    '야스오': { lv1: '야스오의 (P)\'낭인의 길\' 보호막이 충전되어 있으니 (Q)\'천둥의 표창\'으로 먼저 보호막을 제거한 뒤 딜교환을 하세요. (Q)\'강철 폭풍\'의 회오리바람에 띄워지지 않도록 적절한 거리를 유지하며 초반 웨이브를 받아내세요. 야스오가 무리하게 들어오면 뒤로 물러나며 피해를 최소화하세요.', lv3: '(W)\'바람 장막\'이 켜져 있을 때는 (Q)\'천둥의 표창\'이 막히니 스킬을 아끼고 장막이 사라진 뒤에 다시 사용하세요. (E)\'번개 질주\'를 활용해 야스오의 (Q)\'강철 폭풍\' 회오리 궤적에서 빠르게 벗어나며 거리 조절을 하세요. (W)\'전류 방출\'은 표식이 남은 적에게 사용하여 빠르게 기절을 노리는 것이 중요해요.', lv6: '(R)\'날카로운 소용돌이\'를 켜면 방어력과 마법 저항력이 상승하니 야스오의 (E)\'질풍검\' 진입 시 버티며 피해를 주세요. 야스오의 (R)\'최후의 숨결\'은 공중에 떠야 사용 가능하므로 (Q)\'강철 폭풍\' 회오리에 맞지 않도록 주의하세요. 라인을 밀어 두고 정글러를 호출해 야스오를 몰아넣고 궁극기 기절을 연계하세요.', item: '내셔의 이빨을 첫 코어로 가서 공격 속도를 높여 빠르게 기절을 시키고 주문력으로 피해량을 올리세요. 신발은 야스오의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 야스오의 체력이 낮을 때 점화로 확실하게 마무리하여 킬을 가져가세요.' },
    '오공': { lv1: '오공은 (Q)\'파쇄격\'으로 사거리가 길어진 평타를 사용하며 (P)\'바위 피부\' 덕분에 교전이 길어질수록 단단해져요. (Q)\'천둥의 표창\'을 활용해 멀리서 견제하며 오공이 (Q)\'파쇄격\'을 사용하여 접근하는 것을 막아야 해요. 1~2레벨에는 무리하게 붙지 말고 거리를 유지하며 미니언을 챙기세요.', lv3: '오공이 (E)\'근두운 급습\'으로 돌진할 때 (E)\'번개 질주\'를 사용해 위치를 옮기거나 맞받아치세요. (W)\'전류 방출\'을 적절히 사용하여 (P)\'폭풍의 표식\' 스택을 쌓고 기절을 시키는 것이 중요해요. 오공이 (W)\'분신 전사\'로 투명해지면 진짜 위치를 파악하며 스킬을 아끼세요.', lv6: '오공이 (R)\'회전격\'을 사용하여 적을 공중에 띄우면 스킬을 사용할 수 없으니 조심해야 해요. (R)\'날카로운 소용돌이\'를 켜서 방어력을 얻으며 오공의 진입에 맞서 (P)\'폭풍의 표식\'을 터뜨리세요. (R)\'회전격\'이 빠진 타이밍에 (E)\'번개 질주\'를 사용하여 적극적으로 교전하세요.', item: '리안드리의 고통을 첫 코어로 가서 지속적인 피해를 입히세요. 신발은 오공의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 오공이 들어올 때 점화로 빠르게 마무리하세요.' },
    '오로라': { lv1: '오로라는 (Q)\'이중 저주\'를 던지고 다시 사용하여 경로상의 적에게 피해를 주니 옆으로 움직여 피하세요. (Q)\'천둥의 표창\'으로 멀리서 견제하며 미니언과 함께 압박하세요. 초반에는 오로라의 견제를 버티며 체력을 관리하는 것이 중요해요.', lv3: '오로라가 (E)\'마법의 문\'을 사용하면 둔화가 걸리고 뒤로 도약하니, 그 스킬이 빠진 후에 (E)\'번개 질주\'로 거리를 좁히세요. (Q)\'천둥의 표창\'을 맞춘 뒤 (W)\'전류 방출\'로 연계하여 (P)\'폭풍의 표식\'을 쌓아 기절을 노려야 해요. 오로라가 (W)\'장막 너머로\'를 써서 투명해지면 무리하게 쫓지 마세요.', lv6: '오로라가 (R)\'세계의 경계\'를 사용하여 영역을 만들면 그 안에서 싸우기보다 영역 밖으로 나가는 것이 좋아요. (R)\'날카로운 소용돌이\'를 사용해 방어력과 마법 저항력을 얻으며 오로라의 스킬을 받아내세요. 오로라가 (W)\'장막 너머로\'를 이미 써서 빠질 수단이 없을 때 (E)\'번개 질주\'로 빠르게 접근해 킬각을 잡으세요.', item: '첫 코어로 균열 생성기를 선택해 전투 지속력을 높여보세요. 신발은 오로라의 마법 피해를 줄이고 둔화를 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 오로라는 (P)\'영혼 방호술\'로 체력을 회복하므로 점화로 회복 효과를 줄여주세요.' },
    '오른': { lv1: '1~2레벨에는 (Q)\'용암 균열\'이 만드는 용암 기둥 위치를 확인하고 옆으로 비켜서세요. (Q)\'천둥의 표창\'을 사용하여 거리를 유지하며 견제하고, 오른이 (W)\'불꽃 풀무질\'로 전진하며 압박하지 못하게 주의하며 라인을 관리하세요.', lv3: '(W)\'불꽃 풀무질\'의 마지막 불꽃에 맞으면 불안정 상태가 되어 이동 불가 효과 지속 시간이 길어지니 주의하세요. (E)\'번개 질주\'로 접근해 (W)\'전류 방출\'로 표식을 터뜨리고, 오른의 (E)\'화염 돌진\'이 빠진 타이밍을 노려 딜교환을 하세요.', lv6: '(R)\'대장장이 신의 부름\'은 정령이 지나간 자리에 둔화와 불안정 상태를 만드니 정령의 진행 방향을 보고 피하세요. (R)\'날카로운 소용돌이\'를 사용하여 광역 피해를 입히되, 오른이 정령을 밀어내기 전에 (E)\'번개 질주\'를 활용해 빠르게 전투를 끝내세요.', item: '내셔의 이빨을 첫 코어로 올려 공격 속도와 주문력을 확보하세요. 신발은 마법 관통력을 얻기 위해 마법사의 신발을 신으세요.', spell: '점멸과 점화를 추천해요. 오른의 높은 체력을 고려해 점화를 사용하면 킬을 결정짓는 데 도움이 돼요.' },
    '올라프': { lv1: '(Q)\'천둥의 표창\'을 활용해 멀리서 올라프의 체력을 깎으며 견제하세요. 올라프가 (Q)\'역류\'를 던진 뒤 도끼를 다시 주우러 오는 타이밍에 (E)\'번개 질주\'로 거리를 조절하며 공격을 피하세요. 1~2레벨부터 올라프의 근접 교환은 강력하니 붙지 않도록 주의하세요.', lv3: '올라프가 (W)\'버티기\'를 사용하여 보호막을 얻고 공격 속도가 증가할 때는 딜교환을 피하는 것이 좋아요. (Q)\'천둥의 표창\'을 적중시킨 후 (W)\'전류 방출\'을 연계해 빠르게 피해를 입히고 빠져나오세요. (E)\'무모한 강타\'는 고정 피해라 방어력으로 줄일 수 없으니 체력 관리를 신경 써야 해요.', lv6: '올라프가 (R)\'라그나로크\'를 켜면 이동 방해 효과에 면역이 되므로 기절을 노리는 행동은 피하세요. (R)\'날카로운 소용돌이\'를 사용해 방어력과 마법 저항력을 얻으며 교전에 임해야 해요. 올라프의 체력이 낮아지면 (P)\'광전사의 분노\'로 인한 회복량이 급격히 늘어나니 주의하세요.', item: '리안드리의 고통을 첫 코어로 가서 지속적인 피해를 입히세요. 신발은 올라프의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 올라프의 (P)\'광전사의 분노\'로 인한 체력 회복을 점화로 억제하세요.' },
    '요네': { lv1: '요네는 (Q)\'필멸의 검\'을 중첩시켜 돌풍으로 띄우니 거리 조절을 잘해야 해요. (Q)\'천둥의 표창\'으로 요네의 체력을 깎으며 (P)\'폭풍의 표식\'을 쌓아두세요. 요네가 (P)\'사냥꾼의 길\' 효과를 이용해 평타를 계속 치지 못하게 (Q)\'천둥의 표창\'으로 견제하며 대응하세요.', lv3: '요네가 (E)\'영혼해방\'을 쓰고 들어올 때는 (E)\'번개 질주\'로 요네의 돌진을 피하거나 위치를 잡으세요. 요네의 (W)\'영혼 가르기\' 보호막이 발동되면 억지로 딜교환하지 말고 기다리세요. (W)\'전류 방출\'을 사용하여 (P)\'폭풍의 표식\'이 쌓인 요네에게 큰 피해와 기절을 입히며 딜교하세요.', lv6: '요네가 (R)\'운명봉인\'으로 끌어당기며 들어올 때 (R)\'날카로운 소용돌이\'를 켜서 방어력을 높이세요. 요네가 영혼 상태에서 돌아올 때 (P)\'폭풍의 표식\'을 터뜨리면 킬을 노릴 수 있어요. 요네의 (R)\'운명봉인\' 사거리가 길기 때문에 정글러가 올 때 일직선으로 서 있지 않도록 주의하세요.', item: '내셔의 이빨을 첫 코어로 가서 공격 속도와 주문력을 챙기세요. 신발은 요네의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 요네가 (W)\'영혼 가르기\'로 보호막을 얻었을 때 점화로 피해를 더하며 킬을 노리세요.' },
    '요릭': { lv1: '요릭은 (Q)\'최후의 의식\'으로 미니언을 처치하거나 챔피언을 때리면 무덤을 만드니 막타를 치러 다가올 때 (Q)\'천둥의 표창\'으로 견제하세요. 요릭이 (E)\'애도의 안개\'로 표식을 남기면 무덤 근처에서 안개 망령이 깨어나 공격하니 무덤 근처에서는 거리를 조절해야 해요.', lv3: '요릭이 (W)\'망자의 진\'으로 길을 막으면 벽은 공격을 받으면 파괴되니 기본 공격으로 부수거나 사라질 때까지 기다리며 위치를 잡으세요. (E)\'애도의 안개\'에 맞으면 방어력이 줄고 안개 망령이 쫓아오니 (E)\'번개 질주\'로 거리를 벌리세요. 상대 스킬이 빠진 뒤 (W)\'전류 방출\'로 (P)\'폭풍의 표식\'을 터뜨리며 딜교환을 하세요.', lv6: '(R)\'날카로운 소용돌이\'를 사용해 방어력과 마법 저항력을 얻으면 요릭의 공격을 버티기 쉬워져요. 요릭이 (R)\'군도의 장송곡\'으로 안개 마녀를 소환하면 안개 망령이 몰려오니 (E)\'번개 질주\'로 위치를 빠르게 잡으며 대응하세요.', item: '첫 코어 아이템으로 내셔의 이빨을 가서 공격 속도와 주문력을 챙기세요. 신발은 요릭의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 요릭이 (Q)\'최후의 의식\'을 사용하여 체력을 회복하는 것을 점화로 줄이며 킬각을 잡으세요.' },
    '우디르': { lv1: '1~2레벨에는 (Q)\'천둥의 표창\'을 계속 던져 체력을 깎으며 거리를 조절하세요. 우디르가 (E)\'불길 쇄도\'로 진입해 평타 기절을 노리니 무리하게 평타 교환을 하지 말고 계속 뒤로 물러나세요. 미니언 뒤에서 (Q)\'천둥의 표창\'을 적중시켜 (P)\'폭풍의 표식\'을 남기며 압박하세요.', lv3: '우디르가 (E)\'불길 쇄도\'의 기절을 사용한 직후에 (E)\'번개 질주\'로 진입해 (W)\'전류 방출\'과 평타로 (P)\'폭풍의 표식\'을 빠르게 터뜨리세요. (W)\'강철 갑옷\'으로 보호막과 회복을 얻은 상태에서는 딜교환 효율이 낮으니 보호막이 사라질 때까지 기다리세요. (Q)\'야생 발톱\'의 빠른 평타 공격이 들어오기 전에 (Q)\'천둥의 표창\'으로 견제하고 빠르게 빠져나가세요.', lv6: '(R)\'날카로운 소용돌이\'를 켜고 진입해 (P)\'폭풍의 표식\'으로 기절을 노리며 빠르게 피해를 입히세요. 다만 우디르가 (E)\'불길 쇄도\'를 재사용해 이동 불가 효과에 면역이 된 상태라면 기절이 걸리지 않으니 즉시 (E)\'번개 질주\'로 거리를 벌리세요. (R)\'날개 돋친 폭풍\'의 둔화 때문에 움직임이 느려지니 정글 개입을 요청하거나 라인을 당겨서 관리하세요.', item: '내셔의 이빨을 첫 코어로 선택해 공격 속도와 주문력을 높여 (P)\'폭풍의 표식\'을 더 빠르게 터뜨리세요. 신발은 (Q)\'야생 발톱\'의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 우디르가 (W)\'강철 갑옷\'을 통해 체력을 회복하는 것을 방해하고 킬각을 잡으세요.' },
    '우르곳': { lv1: '우르곳은 (Q)\'부식성 폭약\'으로 둔화를 걸며 견제하니 폭약이 떨어지는 위치에서 옆으로 비켜서세요. (Q)\'천둥의 표창\'을 맞혀 표식을 남기며 견제하고, 폭약이 빠진 틈에 막타를 챙기세요.', lv3: '우르곳의 (E)\'경멸\'이 돌진해올 때 (E)\'번개 질주\'를 사용하여 충돌을 피하는 것이 가장 중요해요. (E)\'경멸\'이 빗나간 뒤에 (Q)\'천둥의 표창\'과 (W)\'전류 방출\'을 사용하여 표식을 남기고 짧게 교환하세요. (W)\'심판의 원\'이 활성화된 동안에는 우르곳의 사격 범위 안에서 오래 머물지 마세요.', lv6: '우르곳의 (R)\'불사의 공포\'가 꽂힌 상태에서 체력이 낮으면 처형될 수 있으니 거리를 유지하세요. (R)\'날카로운 소용돌이\'를 사용해 방어력과 마법 저항력을 얻으며 버티는 것이 좋아요. (E)\'경멸\'을 맞고 우르곳 뒤로 던져진다면 (E)\'번개 질주\'로 빠르게 위치를 잡으세요.', item: '내셔의 이빨을 첫 코어로 선택하여 공격 속도와 주문력을 동시에 챙기세요. 신발은 우르곳의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 우르곳이 (E)\'경멸\'로 들어올 때 점멸로 대응하거나 점화로 체력이 낮은 우르곳을 마무리하기 좋아요.' },
    '워윅': { lv1: '(Q)\'천둥의 표창\'으로 계속 견제하며 거리를 벌리세요. 워윅이 (Q)\'야수의 송곳니\'로 도약해 물려고 하면 뒤로 빠지며 대응하세요. (P)\'끝없는 허기\' 때문에 체력이 낮을 때의 회복력이 좋으니 무리하게 교환하지 마세요.', lv3: '워윅이 (E)\'원시의 포효\'를 사용하여 피해 감소를 켜면 공격을 멈추고 기다리세요. 공포가 끝난 뒤 (Q)\'천둥의 표창\'과 평타, (W)\'전류 방출\'을 빠르게 섞어 (P)\'폭풍의 표식\' 기절을 노리세요. (E)\'번개 질주\'는 워윅의 (Q)\'야수의 송곳니\' 진입 경로에서 벗어나거나 빠르게 거리를 벌리는 용도로 사용하세요.', lv6: '(R)\'날카로운 소용돌이\'를 켜면 방어력과 마법 저항력이 올라가니 워윅의 진입을 버티며 피해를 입히세요. 하지만 (R)\'무한의 구속\'에 제압당하면 어떤 스킬도 쓸 수 없으니 워윅의 도약 경로에서 빠르게 벗어나세요. 정글러가 올 때는 (R)\'무한의 구속\'에 먼저 잡히지 않도록 라인을 당겨서 관리하세요.', item: '판금 장화와 모렐로노미콘을 추천해요. 판금 장화로 기본 공격 피해를 줄이고, 모렐로노미콘으로 (P)\'끝없는 허기\'와 (Q)\'야수의 송곳니\'의 회복력을 억제하세요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 워윅의 강력한 체력 회복을 방해하고 킬각을 잡기 좋아요.' },
    '이렐리아': { lv1: '이렐리아는 (Q)\'칼날 쇄도\'로 미니언을 타고 빠르게 접근하며 체력을 회복해요. (Q)\'천둥의 표창\'으로 계속 견제하며 이렐리아가 돌진할 수 있는 미니언과 거리를 두세요. 상대가 무리하게 진입하면 (E)\'번개 질주\'로 빠르게 위치를 옮겨 피해를 최소화하세요.', lv3: '(E)\'쌍검협무\'의 두 칼날이 만나는 지점에 맞으면 기절하고 표식이 생겨 (Q)\'칼날 쇄도\'가 초기화되니 무빙으로 피하세요. (Q)\'천둥의 표창\'과 (E)\'번개 질주\'로 표식을 남긴 뒤 (W)\'전류 방출\'을 사용해 기절을 노리세요. (W)\'저항의 춤\'을 충전하는 동안에는 마법 피해가 감소하니 충전이 끝난 뒤에 스킬을 쓰세요.', lv6: '(R)\'날카로운 소용돌이\'를 켜면 방어력과 마법 저항력이 올라가 (Q)\'칼날 쇄도\'의 피해를 견디기 쉬워요. (R)\'선봉진격검\'에 맞으면 둔화되고 표식이 생겨 추격당하기 쉬우니 결계 밖으로 빠르게 벗어나세요. 상대의 (E)\'쌍검협무\'가 빠진 타이밍에 (E)\'번개 질주\'로 진입하며 (R)\'날카로운 소용돌이\'로 기절을 시키면 킬각을 잡기 좋아요.', item: '내셔의 이빨을 첫 코어로 가서 공격 속도를 높여 (P)\'폭풍의 표식\'을 빠르게 터뜨리세요. 신발은 이렐리아의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 이렐리아의 (Q)\'칼날 쇄도\'를 통한 체력 회복을 방해하고 킬 결정력을 높이세요.' },
    '일라오이': { lv1: '일라오이는 (P)\'고대신의 예언자\'로 지형에 촉수를 소환하니 벽 근처를 피해 라인 중앙에서 싸우세요. (Q)\'천둥의 표창\'으로 멀리서 견제하며 일라오이가 촉수 근처로 오지 못하게 유도해야 해요. 1~2레벨에는 무리하게 딜교환을 하기보다 거리를 유지하며 미니언을 챙기세요.', lv3: '일라오이가 (E)\'영혼의 시험\'을 맞히면 내 영혼이 분리되고 영혼에서 멀어지면 내가 숙주가 되어 촉수가 소환되니 영혼 근처에서 움직임을 조절하세요. 일라오이가 (W)\'혹독한 가르침\'으로 도약할 때 (E)\'번개 질주\'를 사용해 위치를 옮기며 대응하세요. 촉수 공격이 닿지 않는 거리에서 (Q)\'천둥의 표창\'과 (W)\'전류 방출\'로 피해를 주세요.', lv6: '일라오이가 (R)\'믿음의 도약\'을 쓰면 촉수가 많이 소환되니 (R)\'날카로운 소용돌이\'로 빠르게 기절을 걸고 거리를 벌리세요. 일라오이의 궁극기 범위 안에서 버티기보다 (E)\'번개 질주\'로 촉수 사이를 빠져나가는 것이 중요해요. 정글러가 올 때 일라오이가 촉수를 활용하기 쉬우니 라인을 당겨두는 것이 좋아요.', item: '내셔의 이빨을 첫 코어로 올려 공격 속도와 주문력을 동시에 챙기세요. 신발은 일라오이의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화로 일라오이의 (W)\'혹독한 가르침\'이나 촉수 공격을 피해 거리를 벌리기 좋아요.' },
    '자크': { lv1: '(Q)\'천둥의 표창\'으로 자크가 다가오기 전에 멀리서 계속해서 견제하며 체력을 깎아두세요. 자크가 (Q)\'탄성 주먹\'을 사용해 붙으려고 하면 (E)\'번개 질주\'를 활용해 빠르게 거리를 유지하며 대응하세요.', lv3: '자크가 (E)\'새총 발사\'로 날아올 때 (E)\'번개 질주\'로 위치를 옮겨 공중으로 뜨는 것을 방지하세요. 자크가 (W)\'불안정 물질\'을 사용해 주변에 피해를 주려 하면 (Q)\'천둥의 표창\'과 (W)\'전류 방출\'을 맞히고 즉시 거리를 벌리세요.', lv6: '(R)\'날카로운 소용돌이\'를 사용해 방어력을 얻고 자크의 (R)\'바운스!\'가 들어오기 전에 먼저 싸움을 거세요. 자크가 (P)\'세포 분열\'로 인해 조각을 통해 회복하기 전에 (R)\'날카로운 소용돌이\'의 마법 피해로 빠르게 처치하는 것이 중요해요.', item: '내셔의 이빨을 첫 코어로 선택해 공격 속도와 주문력을 높이세요. 신발은 자크의 마법 피해를 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 유체화를 추천해요. 자크의 돌진을 피하며 거리를 조절하기에 적합해요.' },
    '자헨': { lv1: '자헨은 (Q)\'다르킨의 글레이브\'로 빠르게 공격하며 체력을 회복하니 근접해서 싸우지 마세요. (Q)\'천둥의 표창\'을 이용해 거리 조절을 하며 짧게 견제하고 뒤로 빠지는 것이 좋아요. 자헨이 평타로 (P)\'전쟁 단련\' 중첩을 쌓지 못하게 거리 유지를 하며 대응하세요.', lv3: '(W)\'공포의 귀환\'에 끌려가면 위험하니 자헨의 직선 경로에서 벗어나세요. (E)\'찬란한 쇄도\'가 들어올 때 (E)\'번개 질주\'로 빠르게 위치를 옮기며 (W)\'전류 방출\'로 표식을 남기세요. (Q)\'다르킨의 글레이브\'의 재사용 효과인 띄우기 공격을 피한 뒤에 짧은 딜교환을 시도하세요.', lv6: '자헨이 (R)\'단호한 판결\'로 뛰어오르면 낙하 지점을 빠르게 피한 뒤 (R)\'날카로운 소용돌이\'로 기절을 노리세요. (P)\'전쟁 단련\' 결심이 가득 차면 부활할 수 있으니 체력을 모두 깎아도 방심하지 말고 확실히 마무리하세요. 라인을 밀어 넣고 (E)\'번개 질주\'로 빠르게 합류하며 정글러와 함께 움직이세요.', item: '존야의 모래시계를 첫 코어로 선택해 방어력을 챙기고 위험한 순간 경직 상태로 시간을 버세요. 신발은 자헨의 강력한 기본 공격 피해를 줄여 주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 자헨이 (Q)\'다르킨의 글레이브\'와 (R)\'단호한 판결\'로 체력을 계속 회복하니 점화의 치유 감소 효과가 매우 중요해요.' },
    '잭스': { lv1: '(Q)\'천둥의 표창\'을 사용하여 잭스가 다가오기 전에 멀리서 견제하세요. 잭스가 (Q)\'도약 공격\'을 사용하여 붙으려고 하면 (E)\'번개 질주\'로 거리를 벌리며 대응하세요. 잭스의 (P)\'가차없는 맹공\' 패시브가 쌓이기 전에 짧은 딜교환을 유도하세요.', lv3: '잭스가 (E)\'반격\'을 사용하면 기본 공격을 피하며 기절을 시키니 그 동안은 평타를 치지 말고 기다리세요. 잭스의 (E)\'반격\'이 끝난 직후에 (W)\'전류 방출\'과 (Q)\'천둥의 표창\'을 맞춰서 (P)\'폭풍의 표식\'을 쌓으세요. 잭스가 (Q)\'도약 공격\'으로 진입할 때 (E)\'번개 질주\'를 써서 표식을 남기며 거리를 조절하세요.', lv6: '잭스가 (R)\'무기의 달인\'을 사용하여 방어력을 높이면 무리하게 싸우지 말고 거리를 벌리며 (Q)\'천둥의 표창\'으로 견제하세요. 잭스가 (Q)\'도약 공격\'으로 들어올 때 (R)\'날카로운 소용돌이\'를 켜면 (P)\'폭풍의 표식\'을 더 빠르게 쌓아 기절을 노릴 수 있어요. 정글러의 개입이 있을 때 (E)\'번개 질주\'로 유연하게 위치를 잡으며 싸우세요.', item: '리안드리의 고통을 첫 코어로 올려서 스킬로 적을 불태우세요. 신발은 잭스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 정화를 추천해요. 잭스의 (E)\'반격\' 이후에 걸리는 기절을 정화로 빠르게 풀고 대응하세요.' },
    '제이스': { lv1: '제이스가 캐논 상태에서 (Q)\'전격 폭발\'로 멀리서 견제하며 압박을 가해요. (Q)\'천둥의 표창\'을 던져 제이스의 체력을 깎으며 적절한 거리를 유지하세요. 제이스가 (Q)\'하늘로!\'를 써서 돌진해 오면 (E)\'번개 질주\'를 활용해 유연하게 대응하며 (P)\'폭풍의 표식\'을 남기세요.', lv3: '제이스가 (E)\'천둥 강타\'로 밀쳐내려 할 때 (E)\'번개 질주\'로 파고들어 (Q)\'천둥의 표창\'을 맞춰보세요. 제이스의 (E)\'가속 관문\'을 통과한 (Q)\'전격 폭발\'은 사거리가 길어지니 관문 근처에서는 주의해야 해요. (W)\'전류 방출\'을 사용하여 제이스에게 쌓인 표식을 터뜨리며 딜교환을 마무리하세요.', lv6: '(R)\'날카로운 소용돌이\'를 사용하면 방어력과 마법 저항력을 얻어 제이스의 공격을 버티기 수월해져요. 제이스가 (R)\'머큐리 캐논\'으로 방어력을 깎으려 할 때 (E)\'번개 질주\'로 접근해 기절을 노리세요. 제이스의 체력이 낮을 때 (R)\'날카로운 소용돌이\'를 켜고 들어가면 강력한 압박을 줄 수 있어요.', item: '제이스의 물리 피해를 줄이기 위해 판금 장화를 선택하세요. 첫 코어 아이템으로는 공격 속도와 주문력을 모두 챙길 수 있는 내셔의 이빨을 가세요.', spell: '점멸과 점화를 추천해요. 제이스가 형태를 바꾸는 틈에 점화를 사용하여 킬을 노리세요.' },
    '초가스': { lv1: '1~2레벨에는 (Q)\'천둥의 표창\'으로 멀리서 초가스의 체력을 깎으며 견제하세요. 초가스가 (Q)\'파열\'을 사용하여 지면을 부풀려 공중으로 띄우려 할 때 범위를 보고 미리 피하는 것이 중요해요. 초가스의 (E)\'날카로운 가시\'는 사거리가 짧으니 최대한 거리를 유지하며 미니언을 챙기세요.', lv3: '3레벨 이후에는 (E)\'번개 질주\'를 사용하여 초가스의 (Q)\'파열\'을 피하거나 빠르게 거리를 벌리세요. 초가스가 (W)\'흉포한 울부짖음\'을 사용하여 침묵을 걸려고 하면 (E)\'번개 질주\'의 이동 속도로 범위 밖으로 벗어나야 해요. 초가스의 (W)\'흉포한 울부짖음\'이 빠진 뒤에 (Q)\'천둥의 표창\'과 (W)\'전류 방출\'을 맞춰 (P)\'폭풍의 표식\'을 묻히며 딜교환하세요.', lv6: '6레벨 이후에는 (R)\'날카로운 소용돌이\'를 활용해 광범위하게 마법 피해를 입히며 한타를 준비하세요. 초가스가 (R)\'포식\'을 사용하여 큰 고정 피해를 입히려고 하면 체력이 너무 낮아지지 않도록 주의하며 거리를 조절해야 해요. 초가스가 (R)\'포식\'을 미니언에 사용하여 성장하는 순간을 놓치지 말고 (R)\'날카로운 소용돌이\'와 (E)\'번개 질주\'로 압박하며 라인을 관리하세요.', item: '내셔의 이빨을 첫 코어 아이템으로 선택해 공격 속도와 주문력을 모두 챙기세요. 신발은 초가스의 마법 피해와 침묵 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 초가스의 (P)\'육식\'을 통한 체력 회복 효과를 줄이세요.' },
    '카밀': { lv1: '1~2레벨에는 (Q)\'천둥의 표창\'을 계속 던져서 거리를 유지하며 견제하세요. 카밀이 (Q)\'정확성 프로토콜\'을 켜고 빠르게 다가오면 뒤로 무빙하며 평타를 섞어 주세요. (P)\'적응형 방어 체계\' 보호막이 있을 때는 무리하게 딜교환하지 말고 보호막이 사라진 뒤에 공격하세요.', lv3: '(E)\'갈고리 발사\'로 벽을 타고 들어올 때 착지 지점에서 벗어나 기절을 피하는 것이 중요해요. (W)\'전술적 휩쓸기\'의 바깥쪽 절반에 맞으면 느려지고 카밀이 체력을 회복하니 안쪽으로 파고들거나 아예 피하세요. (E)\'번개 질주\'로 카밀의 스킬을 피한 뒤 (Q)\'천둥의 표창\'과 평타로 빠르게 표식을 쌓아 기절을 노리세요.', lv6: '(R)\'마법공학 최후통첩\'에 갇히면 탈출할 수 없으니 벽 근처에서 (E)\'갈고리 발사\' 연계에 당하지 않도록 주의하세요. 갇힌 상태라면 (R)\'날카로운 소용돌이\'를 켜서 방어력과 마법 저항력을 얻고 맞딜을 하며 기절을 노리세요. 라인을 밀 때는 정글러의 개입을 고려해 (E)\'번개 질주\'를 아껴두고 빠르게 빠져나가세요.', item: '내셔의 이빨을 첫 코어로 선택해 공격 속도를 높여 표식을 빠르게 쌓고 피해량을 올리세요. 신발은 카밀의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 카밀이 (W)\'전술적 휩쓸기\'로 체력을 회복하는 것을 점화의 치유 감소로 억제하세요.' },
    '카사딘': { lv1: '(Q)\'천둥의 표창\'으로 계속 견제하세요. 상대의 (P)\'공허석\' 때문에 마법 피해가 줄어드니 너무 무리하지 마세요. (Q)\'무의 구체\' 보호막이 빠진 타이밍에 평타를 섞어 공격하세요.', lv3: '(E)\'번개 질주\'로 빠르게 진입해 (Q)\'천둥의 표창\'과 평타를 맞히고 (P)\'폭풍의 표식\' 기절을 노리세요. 상대의 (E)\'힘의 파동\' 둔화에 걸리면 빠르게 빠져나와야 해요. (W)\'황천의 검\' 강화 평타를 피하며 딜교환하세요.', lv6: '(R)\'날카로운 소용돌이\'를 켜고 진입하되 상대의 (R)\'균열 이동\'으로 거리를 벌리는 것을 주의하세요. 좁은 길목에서 궁극기를 쓰면 피하기 어렵게 만들 수 있어요. 정글러가 왔을 때 (E)\'번개 질주\'로 합류해 기절을 맞히세요.', item: '헤르메스의 발걸음과 구인수의 격노검을 추천해요. 마법 저항력과 강인함으로 (E)\'힘의 파동\' 둔화 시간을 줄이고 공격 속도로 (P)\'폭풍의 표식\'을 빠르게 터뜨리세요.', spell: '점멸과 순간이동을 추천해요. (R)\'날카로운 소용돌이\'와 함께 점멸을 사용해 기습적으로 기절을 맞히고 라인 복귀를 빠르게 하세요.' },
    '카시오페아': { lv1: '(Q)\'천둥의 표창\'으로 견제하면서 거리를 유지하세요. (Q)\'맹독 폭발\'은 범위 스킬이라 미니언 뒤로 피할 수 없고 맞으면 카시오페아의 이동 속도가 오르니 폭발 위치에서 벗어나세요. 초반에는 무리하게 진입하기보다 체력 관리에 집중하세요.', lv3: '(W)\'독기의 늪\'이 깔려 있으면 (E)\'번개 질주\'를 사용할 수 없으니 스킬을 뺀 뒤 진입하세요. (Q)\'천둥의 표창\'과 기본 공격으로 표식을 남기고 (W)\'전류 방출\'로 기절을 노리세요. (E)\'쌍독니\'의 회복량을 줄이기 위해 짧게 딜교해요.', lv6: '(R)\'날카로운 소용돌이\'를 켜고 진입하되 (R)\'석화의 응시\'를 쓰려는 순간 등을 돌리면 기절 대신 둔화만 받으니 시전 타이밍을 보세요. (E)\'번개 질주\'로 빠르게 접근하여 피해를 주면 킬각을 잡기 편해요. 라인을 밀어넣고 정글러와 함께 갱킹을 유도하세요.', item: '헤르메스의 발걸음과 마법사의 최후를 추천해요. 마법 저항력을 높여 (E)\'쌍독니\' 피해를 줄이고 강인함으로 기절 지속시간을 줄이기 위해서예요.', spell: '점멸과 점화를 추천해요. (E)\'쌍독니\'의 체력 회복 효과를 감소시켜 킬 결정력을 높이기 위해서예요.' },
    '케일': { lv1: '케일은 (P)\'거룩한 승천\'으로 성장할수록 강해지는 구간이라 초반에는 힘이 약해요. (Q)\'천둥의 표창\'을 활용해 멀리서 꾸준히 견제하며 케일의 체력을 깎아 두세요. 케일의 (Q)\'광휘의 일격\'에 맞으면 이동 속도와 방어력, 마법 저항력이 감소하니 거리를 잘 조절해야 해요.', lv3: '(E)\'번개 질주\'를 사용하여 빠르게 접근한 뒤 (W)\'전류 방출\'로 (P)\'폭풍의 표식\'을 터뜨리며 딜교환을 시도하세요. 케일이 (E)\'화염주문검\'을 사용하여 잃은 체력에 비례한 추가 피해를 입히려고 할 때는 주의가 필요해요. 케일이 (W)\'천상의 축복\'으로 체력을 회복하며 도망가지 못하도록 (Q)\'천둥의 표창\'으로 표식을 남겨두세요.', lv6: '(R)\'날카로운 소용돌이\'를 사용하여 방어력과 마법 저항력을 얻으며 전투에 임하세요. 케일이 (R)\'신성한 심판\'을 사용하여 자신을 무적 상태로 만들면 모든 피해가 들어가지 않으니 타이밍을 잘 봐야 해요. 케일의 궁극기가 빠진 것을 확인한 뒤에 적극적으로 진입하여 킬을 노리는 것이 좋아요.', item: '헤르메스의 발걸음을 먼저 가서 케일의 마법 피해와 군중 제어 효과에 대비하세요. 첫 코어 아이템은 공격 속도와 주문력을 모두 챙길 수 있는 내셔의 이빨을 추천해요.', spell: '점멸과 점화를 추천해요. 케일이 강해지기 전에 점화로 빠르게 킬을 가져와 성장을 억제해야 해요.' },
    '코그모': { lv1: '코그모가 (Q)\'부식성 침\'으로 방어력을 낮추며 견제하므로 거리를 유지하며 미니언을 받아먹어야 해요. (Q)\'천둥의 표창\'을 활용해 멀리서 표식을 남기며 피해를 입히세요. 1~2레벨에는 무리하게 들어가기보다 안정적으로 파밍하는 것이 중요해요.', lv3: '(E)\'번개 질주\'로 빠르게 접근하여 (P)\'폭풍의 표식\'을 쌓아 기절을 노리는 것이 좋아요. 코그모의 (E)\'공허의 분비물\'이 남긴 흔적을 밟아 이동 속도가 느려지지 않도록 주의하세요. 상대의 사거리 안으로 들어갈 때는 스킬을 한꺼번에 쏟아부어야 해요.', lv6: '(R)\'날카로운 소용돌이\'를 사용해 방어력과 마법 저항력을 얻고 주변 적에게 꾸준히 피해를 입히세요. 코그모가 (R)\'살아있는 곡사포\'로 체력이 낮은 적을 마무리하려 할 수 있으니 주의해야 해요. 상대의 체력이 낮아지면 정글러를 불러 함께 압박하는 것이 효율적이에요.', item: '헤르메스의 발걸음과 리안드리의 고통을 구매하세요. 코그모의 마법 피해를 견디고 지속적인 피해를 입히기 위해서예요.', spell: '점멸과 점화를 추천해요. 코그모는 회복 수단이 없으니 점화는 마무리 피해로 킬을 확정할 때 쓰세요.' },
    '코르키': { lv1: '1~2레벨에는 (Q)\'천둥의 표창\'을 활용해 적의 체력을 깎으며 파밍해요. 코르키가 (Q)\'인광탄\'으로 견제하는 타이밍을 피해 거리 조절을 잘 해야 해요.', lv3: '스킬이 모이면 (E)\'번개 질주\'로 접근하여 (W)\'전류 방출\'로 (P)\'폭풍의 표식\'을 터뜨려 보세요. 코르키가 (E)\'개틀링 건\'으로 방어력과 마법 저항력을 깎기 전에 빠르게 딜교환을 마쳐야 해요.', lv6: '(R)\'날카로운 소용돌이\'를 사용하면 순간적으로 큰 피해를 줄 수 있어요. 코르키가 (R)\'미사일 폭격\'으로 거리를 벌리며 저항할 수 있으니 주의하며 싸워야 해요.', item: '헤르메스의 발걸음과 내셔의 이빨을 추천해요. 코르키의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 사고 내셔의 이빨로 공격 속도를 높여줘요.', spell: '점멸과 점화를 추천해요. 코르키는 회복 수단이 없으니 점화로 마무리 피해를 더해 킬을 노리세요.' },
    '퀸': { lv1: '퀸은 (Q)\'실명 공격\'으로 시야를 좁히고 원거리에서 견제하며 (P)\'매사냥\' 표식으로 강력한 평타를 날려요. (Q)\'천둥의 표창\'을 던져서 퀸의 접근을 막고 표식을 남기며 거리 조절을 하세요. 1~2레벨에는 무리하게 들어가기보다 미니언과 함께 안전하게 성장하는 것이 좋아요.', lv3: '퀸이 (E)\'공중제비\'로 돌진하여 둔화를 거는 타이밍을 조심하고, 그 스킬이 빠지면 (E)\'번개 질주\'를 사용해 거리를 좁히세요. (W)\'전류 방출\'로 (P)\'폭풍의 표식\'을 터뜨리며 딜교환을 하면 효율적이에요. 퀸의 (Q)\'실명 공격\'에 맞기 전에 빠르게 진입하거나 거리를 유지하며 스킬을 맞춰야 해요.', lv6: '(R)\'날카로운 소용돌이\'를 켜고 퀸에게 붙으면 (P)\'폭풍의 표식\'을 쌓아 기절을 유도할 수 있어요. 퀸이 (R)\'후방 지원\'으로 빠르게 도망가거나 위치를 바꿀 수 있으니 주의하며 라인을 관리하세요. 퀸이 (E)\'공중제비\'로 물러날 때 궁극기 범위 안에서 스킬을 지속적으로 적중시키면 킬을 노릴 수 있어요.', item: '첫 코어로 내셔의 이빨을 가서 공격 속도와 주문력을 챙기세요. 신발은 퀸의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 유체화를 추천해요. 유체화로 퀸의 거리를 좁히며 (E)\'번개 질주\'와 함께 압박하기 좋아요.' },
    '크산테': { lv1: '(Q)\'천둥의 표창\'을 사용하여 멀리서 표식을 남기며 크산테를 견제하세요. 크산테가 (Q)\'엔토포 타격\'으로 둔화를 걸며 접근할 때는 거리를 조절하며 무리하게 맞대결하지 마세요.', lv3: '크산테가 (W)\'길을 여는 자\'를 충전하며 돌진할 때는 저지 불가 상태이므로 돌진 경로에서 신속하게 벗어나세요. 크산테가 (E)\'발놀림\'으로 보호막을 얻으며 진입한다면 (E)\'번개 질주\'로 위치를 옮기며 (W)\'전류 방출\'을 맞히는 데 집중하세요.', lv6: '크산테가 (R)\'총공세\'를 사용하여 벽을 넘으며 들어오면 (R)\'날카로운 소용돌이\'를 사용하여 방어력과 마법 저항력을 확보하세요. 크산테는 궁극기 사용 후 방어력이 감소하므로 (W)\'전류 방출\'을 적절히 사용해 피해를 입히세요.', item: '리안드리의 고통을 첫 코어로 선택하여 체력이 높은 크산테에게 지속 피해를 입히세요. 신발은 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 유체화를 추천해요. (E)\'번개 질주\'와 함께 사용하면 크산테의 진입을 피하며 거리를 조절하기 편해요.' },
    '클레드': { lv1: '1~2레벨에는 (Q)\'천둥의 표창\'으로 스칼의 체력을 깎으며 거리를 유지하세요. (Q)\'덫날리기\'에 붙잡히면 끌려가며 큰 피해를 입으니 덫 사거리 밖에서 움직여야 해요. 무리하게 진입하지 말고 원거리 견제에 집중하세요.', lv3: '3레벨 이후 클레드가 (E)\'이랴!\'로 진입할 때 (E)\'번개 질주\'를 사용해 빠르게 위치를 옮기며 피하세요. (W)\'버럭버럭\'이 켜진 상태에서는 강화된 평타의 피해가 매우 크니 정면 승부를 피해야 해요. (Q)\'덫날리기\'가 빗나간 타이밍에 (W)\'전류 방출\'과 평타를 섞어 기절을 노리세요.', lv6: '6레벨 이후 (R)\'돌겨어어억!!!\'으로 빠르게 돌진해오는 클레드는 정글러와 함께 올 가능성이 높으니 라인을 당겨 받으세요. 클레드가 진입하면 (R)\'날카로운 소용돌이\'를 켜서 방어력과 마법 저항력을 얻고 기절로 받아치세요. 스칼에서 내린 클레드는 챔피언 피해량이 줄어드니 이때를 노려 빠르게 처치하세요.', item: '판금 장화를 신어 (W)\'버럭버럭\'의 강화된 기본 공격 피해를 줄이세요. 내셔의 이빨을 첫 코어로 선택해 주문력과 공격 속도를 챙기고 기본 공격을 섞은 딜교환을 강화하세요.', spell: '점멸과 점화를 추천해요. 스칼에서 내린 클레드는 챔피언에게 주는 피해가 줄어드니 점화의 마무리 피해로 빠르게 처치하기 좋아요.' },
    '탐켄치': { lv1: '탐 켄치는 (Q)\'혀 채찍\'으로 견제하며 (P)\'절대 미각\' 중첩을 쌓으니 미니언 뒤에 서서 이를 막으세요. 사거리가 긴 (Q)\'천둥의 표창\'으로 계속해서 툭툭 쳐주며 체력을 깎아두는 것이 중요해요. 평타 교환을 너무 길게 하면 중첩이 쌓여 기절할 수 있으니 주의하세요.', lv3: '(W)\'심연 잠수\'의 잠수 표시가 보이면 즉시 범위 밖으로 벗어나 공중에 뜨지 않도록 하세요. (E)\'번개 질주\'를 이용해 거리 조절을 하며 (Q)\'천둥의 표창\'과 평타로 (P)\'폭풍의 표식\'을 터뜨려 기절을 노리세요. 탐 켄치가 (E)\'두꺼운 피부\'로 보호막을 켰을 때는 딜교환을 잠시 멈추고 보호막이 사라진 뒤 (W)\'전류 방출\'로 피해를 입히세요.', lv6: '(R)\'날카로운 소용돌이\'를 켜고 진입하면 방어력과 마법 저항력을 얻어 버티며 피해를 줄 수 있어요. 하지만 (P)\'절대 미각\' 중첩이 가득 쌓인 상태에서 붙어 있으면 (R)\'집어삼키기\'에 먹힐 수 있으니 매우 조심하세요. 상대의 (W)\'심연 잠수\'가 빠진 시점에 궁극기를 활용해 킬각을 잡고 정글러가 오기 전 라인을 먼저 밀어두세요.', item: '리안드리의 고통을 첫 코어로 선택해 체력이 높은 탐 켄치에게 지속적인 피해를 입히세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음이 적절해요.', spell: '점멸과 점화를 추천해요. 점화로 탐 켄치의 (Q)\'혀 채찍\'과 (E)\'두꺼운 피부\'를 통한 체력 회복을 억제하세요.' },
    '트런들': { lv1: '1~2레벨 구간에 트런들은 (Q)\'깨물기\'로 공격력을 흡수하고 둔화시키며 강하게 압박해요. (Q)\'천둥의 표창\'으로 멀리서 견제하며 트런들의 (Q)\'깨물기\'가 빠졌을 때만 짧게 교환하세요. 트런들은 근처 유닛이 죽으면 (P)\'헌납\'으로 체력을 회복하니 미니언이 많은 곳에서는 조심해요.', lv3: '트런들이 (W)\'얼음 왕국\'을 사용하면 그 영역 안에서 전투를 벌이지 마세요. (E)\'얼음 기둥\'에 밀려나면 거리가 벌어지니 (E)\'번개 질주\'로 위치를 잡으며 트런들의 (Q)\'깨물기\'를 피해야 해요. (Q)\'천둥의 표창\'과 (W)\'전류 방출\'을 활용해 (P)\'폭풍의 표식\'을 남기며 딜교환을 시도하세요.', lv6: '트런들이 (R)\'진압\'을 쓰면 방어력과 마법 저항력을 모두 뺏기니 바로 거리를 벌리세요. (R)\'날카로운 소용돌이\'를 쓰면 방어력과 마법 저항력을 얻어 트런들의 공격을 견디기 수월해요. 트런들은 (P)\'헌납\'으로 체력을 채우며 버티니 정글러와 함께 압박하는 것이 좋아요.', item: '내셔의 이빨을 첫 코어로 올려서 공격 속도와 주문력을 동시에 챙기세요. 신발은 트런들의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 트런들은 (W)\'얼음 왕국\'과 (P)\'헌납\'으로 체력을 많이 회복하니 점화로 회복량을 줄이며 싸우세요.' },
    '트린다미어': { lv1: '(Q)\'천둥의 표창\'으로 계속 견제하면서 거리를 유지하세요. 트린다미어는 (P)\'격노\'를 통해 치명타 확률을 높이므로 평타 교환은 피하고 거리 조절에 집중하세요. 초반 웨이브부터 계속해서 밀어내며 상대가 편하게 파밍하지 못하게 하세요.', lv3: '(E)\'회전 베기\'가 빠진 타이밍에 (Q)\'천둥의 표창\'과 (E)\'번개 질주\'를 활용해 (P)\'폭풍의 표식\'을 빠르게 쌓으세요. (W)\'조롱의 외침\'에 맞았을 때 곧바로 등을 돌리면 둔화되니 천천히 거리를 벌리며 (W)\'전류 방출\'로 피해를 주세요. 상대의 진입 경로를 예측해 (E)\'번개 질주\'로 피하며 딜교환을 주도하세요.', lv6: '(R)\'날카로운 소용돌이\'를 켜고 (P)\'폭풍의 표식\'을 터뜨려 기절시키면 진입하는 상대의 흐름을 끊을 수 있어요. 다만 트린다미어가 (R)\'불사의 분노\'를 켰다면 체력이 깎여도 죽지 않으니, 궁극기 지속시간이 끝날 때까지 버틴 뒤에 마무리하세요. 라인을 밀어 넣고 정글러를 불러 (R)\'불사의 분노\'가 빠진 상태에서 킬각을 잡으세요.', item: '판금 장화와 균열 생성기를 추천해요. 판금 장화는 트린다미어의 강력한 기본 공격 피해를 줄여주고, 균열 생성기는 체력과 지속 전투 능력을 높여줘요.', spell: '점멸과 점화를 추천해요. 트린다미어가 (Q)\'피의 갈망\'으로 체력을 회복하는 것을 점화의 치유 감소 효과로 억제할 수 있어요.' },
    '티모': { lv1: '티모는 (Q)\'실명 다트\'로 시야를 가리고 (E)\'맹독 다트\'를 통해 지속 피해를 입히며 괴롭혀요. (Q)\'천둥의 표창\'을 사용하여 티모의 체력을 깎으며 거리를 조절하세요. 티모가 수풀에서 (P)\'유격 전투\'로 투명해질 수 있으니 주의하며 웨이브를 받아내세요.', lv3: '티모의 (Q)\'실명 다트\'를 맞으면 평타를 통한 (W)\'전류 방출\' 활용이 어려워지니 주의하세요. (Q)\'실명 다트\'는 대상 지정이라 걸어서 피할 수 없으니 이 스킬이 빠진 타이밍에 (E)\'번개 질주\'로 접근해 (Q)\'천둥의 표창\'과 (W)\'전류 방출\'로 딜교환을 시도하세요.', lv6: '(R)\'날카로운 소용돌이\'를 사용하면 방어력과 마법 저항력을 얻으며 폭발적인 피해를 입힐 수 있어요. 티모가 깔아둔 (R)\'유독성 함정\'에 밟히면 이동 속도가 늦춰지니 버섯 위치를 잘 확인하며 진입하세요. 버섯이 없는 길로 (E)\'번개 질주\'를 써서 붙은 뒤 (R)\'날카로운 소용돌이\'를 적중시키면 킬을 노릴 수 있어요.', item: '내셔의 이빨을 코어 아이템으로 선택하여 공격 속도와 주문력을 동시에 챙기세요. 신발은 티모의 (R)\'유독성 함정\'에 걸리는 둔화 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (Q)\'실명 다트\'가 빠진 틈에 점멸로 진입한 뒤 점화로 빠르게 처치하세요.' },
    '판테온': { lv1: '판테온은 (Q)\'혜성의 창\'으로 멀리서 견제하며 초반에 강한 모습을 보여요. (Q)\'천둥의 표창\'을 활용해 판테온의 체력을 깎으면서 적절한 거리를 유지하세요. (P)\'필멸자의 의지\'가 쌓여 강화된 스킬이 나올 때는 맞딜을 피하고 거리를 두는 게 좋아요.', lv3: '판테온의 (W)\'방호의 도약\'은 대상에게 도약해 기절시키니 사거리 안에 오래 머물지 말고 거리를 벌려 두세요. (E)\'방패 돌격\'을 든 동안은 정면 방향의 피해가 막히니 그 시간 동안은 스킬을 아끼고 기다려야 해요. 판테온의 스킬이 빠진 뒤에 (W)\'전류 방출\'을 섞어 짧게 딜교환을 시도하세요.', lv6: '판테온이 (R)\'거대 유성\'을 사용해 공중에서 떨어지면 착지 지점을 확인하고 위치를 옮겨 피해를 피하세요. (R)\'날카로운 소용돌이\'를 사용하여 판테온의 진입에 맞받아치며 (P)\'폭풍의 표식\'을 남겨 기절을 노리세요. 판테온이 (W)\'방호의 도약\'으로 기절을 걸면 스킬을 쓸 수 없으니 주의하며 싸워야 해요.', item: '첫 코어로 리안드리의 고통을 가서 지속적인 피해를 입히세요. 신발은 판테온의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 정화를 추천해요. 정화로 판테온의 (W)\'방호의 도약\' 기절을 풀고 대응할 수 있어요.' },
    '피들스틱': { lv1: '1~2레벨에는 (Q)\'천둥의 표창\'을 활용해 최대한 멀리서 견제하며 거리를 유지하세요. 상대가 수풀에 숨어 (E)\'수확\'으로 둔화를 거는 것을 경계하며 미니언 사이에서 안전하게 파밍해야 해요. 초반에는 무리한 진입보다 표식을 남기는 것에 집중하며 안정적으로 성장하세요.', lv3: '(E)\'번개 질주\'를 사용하여 빠르게 접근한 뒤 (W)\'전류 방출\'로 (P)\'폭풍의 표식\'을 터뜨려 딜교환을 하세요. 상대가 (E)\'수확\'을 먼저 사용하게 유도하여 침묵을 피하거나, (W)\'풍작\'으로 체력을 회복할 때 (Q)\'천둥의 표창\'을 맞춰서 피해를 주어야 해요. (E)\'수확\'의 중심부에 맞아 침묵에 걸리지 않도록 주의하며 스킬을 사용하세요.', lv6: '상대가 (R)\'까마귀 폭풍\'으로 진입하면 (R)\'날카로운 소용돌이\'를 켜서 방어력과 마법 저항력을 확보하며 버티세요. (P)\'폭풍의 표식\'이 터질 때까지 스킬을 연계하여 킬각을 보고, 적의 (Q)\'공포\' 범위에 들어가지 않게 주의해야 해요. 라인을 적당히 밀어 넣고 정글러의 도움을 받을 수 있도록 시야를 확보하세요.', item: '헤르메스의 발걸음과 마법사의 최후를 추천해요. 마법 저항력과 강인함으로 상대의 제어 효과를 견디고 마법 피해를 줄이기 위해서예요.', spell: '점멸과 정화를 추천해요. 상대의 (Q)\'공포\'나 (E)\'수확\'의 침묵을 빠르게 풀어 대응하며 전투를 이어가기 위해서예요.' },
    '피오라': { lv1: '1~2레벨에는 (Q)\'천둥의 표창\'으로 멀리서 견제하며 거리를 유지하세요. 피오라가 (Q)\'찌르기\'로 접근해 (P)\'치명적인 검무\'로 급소를 가격하면 체력 관리가 어려워지니 주의해야 해요. (E)\'번개 질주\'를 활용해 피오라의 돌진 경로를 피하며 거리를 벌리는 것이 좋아요.', lv3: '피오라가 (W)\'응수\'를 켜면 모든 공격과 이동 불가 효과를 막아내고, 이동 불가를 막아내면 공격한 나를 기절시키니 (W)\'응수\'가 켜진 동안은 스킬을 아끼세요. (W)\'응수\'가 끝난 뒤 (W)\'전류 방출\'로 표식을 남기며 딜교환을 하세요. (E)\'번개 질주\'로 위치를 옮겨 피오라의 (Q)\'찌르기\' 돌진 경로를 피하세요.', lv6: '(R)\'날카로운 소용돌이\'를 사용해 방어력과 마법 저항력을 얻으며 피오라의 공격을 버티세요. 피오라가 (R)\'대결투\'를 사용하여 급소를 드러내면 (E)\'번개 질주\'로 유연하게 움직이며 급소를 가격당하지 않도록 조심하세요. 라인을 빠르게 밀어 정글러의 개입을 유도하거나 (P)\'폭풍의 표식\'으로 킬각을 노려보세요.', item: '첫 코어로 리안드리의 고통을 올려 지속적인 피해를 입히세요. 신발은 피오라의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 피오라가 (P)\'치명적인 검무\'를 통해 체력을 회복하는 것을 억제하세요.' },
    '하이머딩거': { lv1: '하이머딩거는 (Q)\'H-28 G 진화형 포탑\'을 설치해 라인을 압박하고 포탑 주변에서 이동 속도가 올라가요. 1~2레벨에는 (Q)\'천둥의 표창\'으로 견제하며 포탑의 사선을 피하세요. 포탑이 쌓이기 전에 미니언을 챙기며 거리 조절을 하는 것이 중요해요.', lv3: '하이머딩거의 (E)\'CH-2 전자폭풍 수류탄\'에 직격되면 기절하니 수류탄의 궤적을 잘 보고 피하세요. 상대의 수류탄이 빠졌을 때 (E)\'번개 질주\'를 사용해 포탑 사이로 파고들며 (W)\'전류 방출\'로 피해를 입히세요. (W)\'마법공학 초소형 로켓\'이 모이는 지점을 피하며 딜교환을 시도해요.', lv6: '하이머딩거가 (R)\'업그레이드!!!\'를 사용해 강화된 스킬을 쓰기 전에는 진입을 자제하세요. 상대의 포탑이 적을 때 (R)\'날카로운 소용돌이\'를 켜고 (E)\'번개 질주\'로 진입해 (P)\'폭풍의 표식\'을 터뜨려 킬각을 보세요. 포탑이 너무 많다면 무리하게 들어가지 말고 라인을 먼저 정리하며 정글러를 기다리세요.', item: '내셔의 이빨을 첫 코어로 올려 공격 속도와 주문력을 동시에 챙기세요. 신발은 마법 피해를 견디고 기절 지속 시간을 줄이는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 하이머딩거가 포탑 뒤에서 버티지 못하게 점화로 빠르게 처치하세요.' }
  }
};
// 사이트 등록: window.TOP_MATCHUPS['내챔피언_상대'] = { lvl1, lvl3, lvl6, item, spell } (이름의 띄어쓰기는 제거)
(function (d) {
  var g = typeof window !== 'undefined' ? window : globalThis;
  g.TOP_MATCHUPS = g.TOP_MATCHUPS || {};
  var me = d.champion.replace(/\s+/g, '');
  Object.keys(d.matchups).forEach(function (opp) {
    var m = d.matchups[opp];
    g.TOP_MATCHUPS[me + '_' + opp.replace(/\s+/g, '')] = { lvl1: m.lv1, lvl3: m.lv3, lvl6: m.lv6, item: m.item, spell: m.spell };
  });
})(top_kennen);
if (typeof module !== 'undefined') module.exports = top_kennen;
